INSERT INTO categories (id, name, description) VALUES ('gate-engineering', 'GATE (Engineering)', 'Engineering mathematics, general aptitude, and core CS/EE/ME/CE fundamentals for GATE-style exams.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('gate-engineering-bank', NULL, 'GATE Engineering Prep', 'gate', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('gate-engineering-bank', 'gate-engineering');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00001', 'gate-engineering-bank', 'Engineering Mathematics', 0, 0, 'What is the rank of a matrix, and how is it determined?', 'The **rank** of a matrix is the maximum number of linearly independent rows (or equivalently, columns) in it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00002', 'gate-engineering-bank', 'Engineering Mathematics', 0, 1, 'State the relationship between the rank of a coefficient matrix and the solvability of a system of linear equations `Ax = b`.', 'For a system `Ax = b` with coefficient matrix `A` and augmented matrix `[A|b]`:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00003', 'gate-engineering-bank', 'Engineering Mathematics', 0, 2, 'What are eigenvalues and eigenvectors of a square matrix?', 'For a square matrix `A`, a non-zero vector `x` is an **eigenvector** with **eigenvalue** `λ` if `Ax = λx`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00004', 'gate-engineering-bank', 'Engineering Mathematics', 0, 3, 'What is the relation between the eigenvalues of a matrix and its trace and determinant?', 'The **sum of the eigenvalues** of a square matrix equals its **trace** (sum of diagonal elements), and the **product of the eigenvalues** equals its **determinant**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00005', 'gate-engineering-bank', 'Engineering Mathematics', 0, 4, 'How do the eigenvalues of a triangular matrix relate to the matrix itself?', 'For any **upper triangular**, **lower triangular**, or **diagonal matrix**, the eigenvalues are exactly the entries on the **main diagonal**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00006', 'gate-engineering-bank', 'Engineering Mathematics', 0, 5, 'What is a symmetric matrix''s key spectral property?', 'A **real symmetric matrix** always has **real eigenvalues**, and eigenvectors corresponding to distinct eigenvalues are **orthogonal**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00007', 'gate-engineering-bank', 'Engineering Mathematics', 0, 6, 'Define the determinant of a 2x2 and 3x3 matrix.', 'For a `2×2` matrix `[[a,b],[c,d]]`, the determinant is `ad − bc`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00008', 'gate-engineering-bank', 'Engineering Mathematics', 0, 7, 'What does it mean for a set of vectors to be linearly independent?', 'Vectors `v1, v2, ..., vn` are **linearly independent** if the only solution to `c1*v1 + c2*v2 + ... + cn*vn = 0` is `c1 = c2 = ... = cn = 0`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00009', 'gate-engineering-bank', 'Engineering Mathematics', 0, 8, 'What is the condition for a square matrix to be invertible?', 'A square matrix `A` is **invertible** (non-singular) if and only if `det(A) ≠ 0`, equivalently if `rank(A)` equals its order `n`, equivalently if its rows (or columns) are linearly independent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00010', 'gate-engineering-bank', 'Engineering Mathematics', 0, 9, 'State the Cayley-Hamilton theorem.', 'The **Cayley-Hamilton theorem** states that every square matrix satisfies its own **characteristic equation**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00011', 'gate-engineering-bank', 'Engineering Mathematics', 0, 10, 'What are the possible types of solutions for a homogeneous system `Ax = 0`?', 'A homogeneous system `Ax = 0` always has the **trivial solution** `x = 0`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00012', 'gate-engineering-bank', 'Engineering Mathematics', 0, 11, 'What is the limit definition of the derivative of a function `f(x)` at a point?', 'The derivative is defined as the limit `f''(x) = lim(h→0) [f(x+h) − f(x)] / h`, provided this limit exists.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00013', 'gate-engineering-bank', 'Engineering Mathematics', 0, 12, 'State Rolle''s theorem and its geometric meaning.', '**Rolle''s theorem**: if `f` is continuous on `[a,b]`, differentiable on `(a,b)`, and `f(a) = f(b)`, then there exists some `c ∈ (a,b)` such that `f''(c) = 0`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00014', 'gate-engineering-bank', 'Engineering Mathematics', 0, 13, 'State the Lagrange Mean Value Theorem.', 'If `f` is continuous on `[a,b]` and differentiable on `(a,b)`, then there exists `c ∈ (a,b)` such that `f''(c) = [f(b) − f(a)] / (b − a)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00015', 'gate-engineering-bank', 'Engineering Mathematics', 0, 14, 'What is the condition for a function of two variables to have a local maximum or minimum at a critical point?', 'At a critical point `(a,b)` where `fx = fy = 0`, define `D = fxx*fyy − (fxy)^2` (the **Hessian discriminant**).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00016', 'gate-engineering-bank', 'Engineering Mathematics', 0, 15, 'What is a Taylor series expansion of a function `f(x)` about a point `a`?', 'The **Taylor series** of `f(x)` about `x = a` is `f(x) = f(a) + f''(a)(x−a) + f''''(a)(x−a)^2/2! + f''''''(a)(x−a)^3/3! + ...`
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00017', 'gate-engineering-bank', 'Engineering Mathematics', 0, 16, 'What is the formula for integration by parts?', 'Integration by parts states `∫u dv = uv − ∫v du`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00018', 'gate-engineering-bank', 'Engineering Mathematics', 0, 17, 'How is the area between two curves `y = f(x)` and `y = g(x)` computed using definite integrals?', 'If `f(x) ≥ g(x)` on `[a,b]`, the area between the curves is `∫[a to b] (f(x) − g(x)) dx`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00019', 'gate-engineering-bank', 'Engineering Mathematics', 0, 18, 'What is the significance of a partial derivative in multivariable calculus?', 'A **partial derivative** `∂f/∂x` measures the rate of change of a multivariable function with respect to one variable, **holding all other variables constant**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00020', 'gate-engineering-bank', 'Engineering Mathematics', 0, 19, 'State the condition for a function `f(x,y)` to be differentiable versus merely having partial derivatives.', 'The mere existence of partial derivatives `fx` and `fy` at a point does **not guarantee differentiability**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00021', 'gate-engineering-bank', 'Engineering Mathematics', 0, 20, 'What is the formula for changing the order of integration in a double integral?', 'To change the order of integration, the original region of integration described by the limits must first be **sketched**, and then re-described with the integration variables swapped, adjusting the limits to match the same geometric region — the value of the double integral remains unchanged.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00022', 'gate-engineering-bank', 'Engineering Mathematics', 0, 21, 'Define a general first-order linear ordinary differential equation and its solution method.', 'A first-order linear ODE has the form `dy/dx + P(x)y = Q(x)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00023', 'gate-engineering-bank', 'Engineering Mathematics', 0, 22, 'What is the general solution form for a second-order linear homogeneous ODE with constant coefficients `ay'''' + by'' + cy = 0`?', 'Form the **auxiliary (characteristic) equation** `am^2 + bm + c = 0`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00024', 'gate-engineering-bank', 'Engineering Mathematics', 0, 23, 'What distinguishes an exact differential equation `M(x,y)dx + N(x,y)dy = 0`?', 'The equation is **exact** if `∂M/∂y = ∂N/∂x`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00025', 'gate-engineering-bank', 'Engineering Mathematics', 0, 24, 'What is a Bernoulli differential equation and how is it solved?', 'A **Bernoulli equation** has the form `dy/dx + P(x)y = Q(x)y^n` where `n ≠ 0, 1`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00026', 'gate-engineering-bank', 'Engineering Mathematics', 0, 25, 'What is the method of variation of parameters used for?', '**Variation of parameters** finds a **particular solution** of a non-homogeneous linear ODE `ay'''' + by'' + cy = f(x)` when the method of undetermined coefficients is not applicable (e.g., when `f(x)` is `tan(x)` or `sec(x)`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00027', 'gate-engineering-bank', 'Engineering Mathematics', 0, 26, 'What is a Laplace transform, and why is it used in solving differential equations?', 'The **Laplace transform** of a function `f(t)` is `F(s) = ∫[0 to ∞] e^(−st) f(t) dt`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00028', 'gate-engineering-bank', 'Engineering Mathematics', 0, 27, 'Define conditional probability and state Bayes'' theorem.', '**Conditional probability**: `P(A|B) = P(A ∩ B) / P(B)`, provided `P(B) > 0`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00029', 'gate-engineering-bank', 'Engineering Mathematics', 0, 28, 'What are the mean and variance of a Binomial distribution `B(n, p)`?', 'For a Binomial random variable with `n` trials and success probability `p`:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00030', 'gate-engineering-bank', 'Engineering Mathematics', 0, 29, 'What are the mean and variance of a Poisson distribution with parameter `λ`?', 'For a Poisson distribution with rate parameter `λ`, both the **mean and variance equal `λ`**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00031', 'gate-engineering-bank', 'Engineering Mathematics', 0, 30, 'What is the probability density function of a Normal (Gaussian) distribution?', 'The PDF of a Normal distribution with mean `μ` and standard deviation `σ` is `f(x) = (1 / (σ√(2π))) * e^(−(x−μ)^2 / (2σ^2))`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00032', 'gate-engineering-bank', 'Engineering Mathematics', 0, 31, 'Define the expectation and variance of a discrete random variable.', 'The **expectation (mean)** is `E[X] = Σ x * P(X=x)` over all possible values of `X`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00033', 'gate-engineering-bank', 'Engineering Mathematics', 0, 32, 'What is the Central Limit Theorem?', 'The **Central Limit Theorem** states that the sampling distribution of the **sum (or mean)** of a large number of i.i.d. random variables, each with finite mean and variance, approaches a **Normal distribution**, regardless of the original distribution''s shape, as the sample size `n → ∞`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00034', 'gate-engineering-bank', 'Engineering Mathematics', 0, 33, 'How are two events A and B defined to be statistically independent?', 'Events `A` and `B` are **independent** if and only if `P(A ∩ B) = P(A) * P(B)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00035', 'gate-engineering-bank', 'Engineering Mathematics', 0, 34, 'What is the correlation coefficient and what range of values does it take?', 'The **Pearson correlation coefficient** `r` measures the strength and direction of a **linear relationship** between two variables, computed as `r = Cov(X,Y) / (σX * σY)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00036', 'gate-engineering-bank', 'Engineering Mathematics', 0, 35, 'Distinguish between mean, median, and mode as measures of central tendency.', 'The **mean** is the arithmetic average of all data points.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00037', 'gate-engineering-bank', 'Engineering Mathematics', 0, 36, 'What is the Newton-Raphson method for finding roots of an equation `f(x) = 0`?', 'The **Newton-Raphson iteration** is `x(n+1) = x(n) − f(x(n)) / f''(x(n))`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00038', 'gate-engineering-bank', 'Engineering Mathematics', 0, 37, 'What is the Bisection method for root-finding, and what is its rate of convergence?', 'The **Bisection method** repeatedly halves an interval `[a,b]` where `f(a)` and `f(b)` have opposite signs, selecting the sub-interval where the sign change occurs.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00039', 'gate-engineering-bank', 'Engineering Mathematics', 0, 38, 'State the Trapezoidal rule for numerical integration.', 'The **Trapezoidal rule** approximates `∫[a to b] f(x)dx ≈ (h/2) * [f(x0) + 2(f(x1)+...+f(x(n-1))) + f(xn)]`, where `h = (b−a)/n` is the step size.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00040', 'gate-engineering-bank', 'Engineering Mathematics', 0, 39, 'State Simpson''s 1/3 rule for numerical integration and its condition on the number of intervals.', '**Simpson''s 1/3 rule**: `∫[a to b] f(x)dx ≈ (h/3) * [f(x0) + 4(odd-indexed terms) + 2(even-indexed terms) + f(xn)]`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00041', 'gate-engineering-bank', 'Engineering Mathematics', 0, 40, 'What is Lagrange''s interpolation formula used for?', '**Lagrange interpolation** constructs a unique polynomial of degree at most `n−1` that passes exactly through `n` given data points, without requiring the points to be equally spaced.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00042', 'gate-engineering-bank', 'Engineering Mathematics', 0, 41, 'What is the order of convergence of the Newton-Raphson method compared to the Regula-Falsi (false position) method?', '**Newton-Raphson** has **quadratic (second-order)** convergence near a simple root.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00043', 'gate-engineering-bank', 'Engineering Mathematics', 0, 42, 'What is a propositional logic tautology, and how is it identified?', 'A **tautology** is a compound proposition that is **true for every possible truth value assignment** of its variables.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00044', 'gate-engineering-bank', 'Engineering Mathematics', 0, 43, 'Define a partial order relation and give its three required properties.', 'A relation `R` on a set `S` is a **partial order** if it is:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00045', 'gate-engineering-bank', 'Engineering Mathematics', 0, 44, 'What is an equivalence relation, and what structure does it induce on a set?', 'A relation is an **equivalence relation** if it is **reflexive, symmetric, and transitive**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00046', 'gate-engineering-bank', 'Engineering Mathematics', 0, 45, 'Define a bijective function and state why it matters for counting.', 'A function `f: A → B` is **bijective** if it is both **injective (one-to-one)** and **surjective (onto)** — every element of `B` has exactly one pre-image in `A`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00047', 'gate-engineering-bank', 'Engineering Mathematics', 0, 46, 'What is the Pigeonhole Principle?', 'The **Pigeonhole Principle** states that if `n` items are placed into `m` containers where `n > m`, then at least one container must hold **more than one item**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00048', 'gate-engineering-bank', 'Engineering Mathematics', 0, 47, 'How many ways can `r` objects be chosen from `n` distinct objects (combinations), and how does this differ from permutations?', 'The number of **combinations** (order doesn''t matter) is `C(n,r) = n! / (r!(n−r)!)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00049', 'gate-engineering-bank', 'Engineering Mathematics', 0, 48, 'What is the Handshaking Lemma in graph theory?', 'The **Handshaking Lemma** states that the **sum of degrees of all vertices** in an undirected graph equals **twice the number of edges**: `Σ deg(v) = 2|E|`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00050', 'gate-engineering-bank', 'Engineering Mathematics', 0, 49, 'What conditions must a connected graph satisfy to have an Eulerian circuit?', 'A connected graph has an **Eulerian circuit** (a closed walk using every edge exactly once) if and only if **every vertex has even degree**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00051', 'gate-engineering-bank', 'Engineering Mathematics', 0, 50, 'What is the chromatic number of a graph?', 'The **chromatic number** `χ(G)` is the minimum number of colors needed to color the vertices of `G` such that **no two adjacent vertices share the same color**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00052', 'gate-engineering-bank', 'Engineering Mathematics', 0, 51, 'What does it mean for a graph to be bipartite, and how is this characterized?', 'A graph is **bipartite** if its vertices can be split into two disjoint sets such that every edge connects a vertex in one set to a vertex in the other (no edges within a set).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00053', 'gate-engineering-bank', 'Engineering Mathematics', 0, 52, 'Define a tree in graph theory and state the relation between its vertices and edges.', 'A **tree** is a **connected acyclic graph**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00054', 'gate-engineering-bank', 'Engineering Mathematics', 0, 53, 'What is a spanning tree of a graph, and how is a minimum spanning tree found?', 'A **spanning tree** of a connected graph `G` is a subgraph that includes all vertices of `G`, is connected, and contains no cycles (so it has `n−1` edges).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00055', 'gate-engineering-bank', 'Engineering Mathematics', 0, 54, 'What is the Principle of Mathematical Induction?', 'To prove a statement `P(n)` holds for all natural numbers `n ≥ n0`, induction requires showing the **base case** `P(n0)` is true, and the **inductive step**: assuming `P(k)` is true (inductive hypothesis) implies `P(k+1)` is true.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00056', 'gate-engineering-bank', 'Engineering Mathematics', 0, 55, 'What are the four axioms that define an algebraic group under a binary operation?', 'A set `G` with a binary operation `*` forms a **group** if it satisfies: **closure** (`a*b ∈ G`), **associativity** (`(a*b)*c = a*(b*c)`), **identity** (an element `e` with `a*e = e*a = a`), and **inverse** (for every `a`, there exists `a⁻¹` with `a*a⁻¹ = e`).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00057', 'gate-engineering-bank', 'Engineering Mathematics', 0, 56, 'What distinguishes a ring from a group in abstract algebra?', 'A **ring** is a set with two operations, `+` and `*`, where the set forms an **abelian group under addition**, is **associative under multiplication**, and multiplication **distributes over addition** — but multiplication need not have inverses, unlike a group''s single operation which must have inverses for every element.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00058', 'gate-engineering-bank', 'Engineering Mathematics', 0, 57, 'State the Cauchy-Riemann equations and their significance for complex functions.', 'For `f(z) = u(x,y) + i*v(x,y)` to be **analytic (holomorphic)** at a point, the **Cauchy-Riemann equations** `∂u/∂x = ∂v/∂y` and `∂u/∂y = −∂v/∂x` must hold, along with continuity of these partial derivatives.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00059', 'gate-engineering-bank', 'Engineering Mathematics', 0, 58, 'What is a singular point (singularity) of a complex function, and how is a residue computed at a simple pole?', 'A **singularity** is a point where a complex function fails to be analytic.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00060', 'gate-engineering-bank', 'Engineering Mathematics', 0, 59, 'What is the formula for the gradient of a scalar function, and what does its direction indicate?', 'The **gradient** of a scalar field `f(x,y,z)` is `∇f = (∂f/∂x, ∂f/∂y, ∂f/∂z)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00061', 'gate-engineering-bank', 'Engineering Mathematics', 0, 60, 'Define divergence and curl of a vector field, and what each measures physically.', '**Divergence** `∇ · F` measures the net **outward flux** per unit volume at a point — a source (`div > 0`) or sink (`div < 0`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00062', 'gate-engineering-bank', 'Engineering Mathematics', 0, 61, 'What is the formula relating a matrix''s inverse to its adjoint and determinant?', 'For an invertible square matrix `A`, `A⁻¹ = adj(A) / det(A)`, where `adj(A)` (the **adjugate**) is the transpose of the cofactor matrix of `A`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00063', 'gate-engineering-bank', 'Engineering Mathematics', 0, 62, 'What is the geometric multiplicity versus algebraic multiplicity of an eigenvalue?', 'The **algebraic multiplicity** of an eigenvalue `λ` is the number of times it appears as a root of the characteristic polynomial.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00064', 'gate-engineering-bank', 'General Aptitude', 1, 0, 'In GATE General Aptitude, what are the four broad categories tested, and what percentage of total marks do they carry?', 'GATE General Aptitude covers **Verbal Ability**, **Quantitative Aptitude**, **Analytical Aptitude**, and **Spatial Aptitude**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00065', 'gate-engineering-bank', 'General Aptitude', 1, 1, 'Choose the correct word: ''The committee could not reach a consensus, so the decision was ___ to next week.''', 'The correct word is **''deferred''** (postponed), not ''differed'' (a common confusable pair).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00066', 'gate-engineering-bank', 'General Aptitude', 1, 2, 'Identify the odd one out: Fahrenheit, Celsius, Kelvin, Joule.', '**Joule** is the odd one out.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00067', 'gate-engineering-bank', 'General Aptitude', 1, 3, 'Complete the analogy: Pen is to Write as Knife is to ___.', 'The correct answer is **''Cut''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00068', 'gate-engineering-bank', 'General Aptitude', 1, 4, 'What is the plural form of ''syllabus'', and what is the plural of ''phenomenon''?', 'The plural of **''syllabus''** is **''syllabi''** (or ''syllabuses'', also acceptable).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00069', 'gate-engineering-bank', 'General Aptitude', 1, 5, 'Choose the correctly spelled word: ''accomodate'', ''acommodate'', ''accommodate'', ''acomodate''.', 'The correctly spelled word is **''accommodate''**, with **double ''c'' and double ''m''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00070', 'gate-engineering-bank', 'General Aptitude', 1, 6, 'Fill in the blank with the correct preposition: ''She is good ___ mathematics but weak ___ grammar.''', 'The correct prepositions are **''at''** and **''in''**: ''She is good **at** mathematics but weak **in** grammar.''
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00071', 'gate-engineering-bank', 'General Aptitude', 1, 7, 'What is the meaning of the idiom ''to bite the bullet''?', '''To bite the bullet'' means **to face a difficult or unpleasant situation with courage**, accepting it as inevitable.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00072', 'gate-engineering-bank', 'General Aptitude', 1, 8, 'Identify the type of sentence: ''Although it was raining heavily, the match continued.''', 'This is a **complex sentence**, because it contains one **independent clause** (''the match continued'') and one **dependent (subordinate) clause** (''Although it was raining heavily'') joined by the subordinating conjunction ''Although''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00073', 'gate-engineering-bank', 'General Aptitude', 1, 9, 'Choose the word nearest in meaning to ''ubiquitous''.', 'The word nearest in meaning to **''ubiquitous''** is **''omnipresent''** (present everywhere).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00074', 'gate-engineering-bank', 'General Aptitude', 1, 10, 'Choose the word opposite in meaning to ''austere''.', 'The antonym of **''austere''** (severe, strict, plain) is **''luxurious''** (or ''lavish/ornate'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00075', 'gate-engineering-bank', 'General Aptitude', 1, 11, 'In the sentence ''Neither the manager nor the employees ___ aware of the policy change,'' which verb form is correct?', 'The correct verb form is **''were''**: ''Neither the manager nor the employees **were** aware of the policy change.''
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00076', 'gate-engineering-bank', 'General Aptitude', 1, 12, 'Which sentence demonstrates correct subject-verb agreement: ''Each of the students have submitted their assignment'' or ''Each of the students has submitted their assignment''?', 'The correct sentence is **''Each of the students has submitted their assignment.''**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00077', 'gate-engineering-bank', 'General Aptitude', 1, 13, 'A reading passage states ''All eagles can fly. Some birds cannot fly. Therefore, some birds are not eagles.'' Is this a valid logical deduction?', '**Yes, the conclusion is valid.**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00078', 'gate-engineering-bank', 'General Aptitude', 1, 14, 'Statement: ''All pilots are trained professionals. No trained professional is careless.'' What can be concluded about pilots and carelessness?', 'The valid conclusion is: **''No pilot is careless.''**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00079', 'gate-engineering-bank', 'General Aptitude', 1, 15, 'If ''CODE'' is written as ''DPEF'' using a letter-shift cipher, what is ''WORD'' written as?', 'Each letter is shifted **forward by one position** in the alphabet (C→D, O→P, D→E, E→F).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00080', 'gate-engineering-bank', 'General Aptitude', 1, 16, 'In a certain code, if 1 = A, 2 = B, ..., 26 = Z, what word does the sequence 7-15-16-5 represent?', 'Mapping each number to its corresponding letter: `7=G, 15=O, 16=P, 5=E`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00081', 'gate-engineering-bank', 'General Aptitude', 1, 17, 'Five friends P, Q, R, S, T sit in a row. P is to the immediate left of Q, R is at one end, and S is between Q and T. What is one valid seating order?', 'One valid arrangement is **R, P, Q, S, T** (left to right).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00082', 'gate-engineering-bank', 'General Aptitude', 1, 18, 'What day of the week was 15 August 1947 (India''s Independence Day)?', '15 August 1947 was a **Friday**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00083', 'gate-engineering-bank', 'General Aptitude', 1, 19, 'At 3:15, what is the angle between the hour and minute hands of a clock?', 'The angle is **7.5 degrees**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00084', 'gate-engineering-bank', 'General Aptitude', 1, 20, 'A sum of money doubles itself in 8 years at simple interest. In how many years will it become four times itself?', 'The sum becomes **24 years**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00085', 'gate-engineering-bank', 'General Aptitude', 1, 21, 'A sum of ₹10,000 is invested at 10% per annum compound interest for 2 years. What is the compound interest earned?', 'The compound interest is **₹2,100**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00086', 'gate-engineering-bank', 'General Aptitude', 1, 22, 'If the price of an item is increased by 20% and then decreased by 20%, what is the net percentage change in price?', 'The net change is a **4% decrease**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00087', 'gate-engineering-bank', 'General Aptitude', 1, 23, 'A shopkeeper marks an item 40% above cost price and offers a 25% discount on the marked price. What is the shopkeeper''s net profit percentage?', 'The net profit is **5%**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00088', 'gate-engineering-bank', 'General Aptitude', 1, 24, 'Two pipes A and B can fill a tank in 12 hours and 15 hours respectively. If both pipes are opened together, how long will they take to fill the tank?', 'They take **(60/9) = 6⅔ hours** (6 hours 40 minutes).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00089', 'gate-engineering-bank', 'General Aptitude', 1, 25, 'A can complete a piece of work in 10 days, and B can complete the same work in 15 days. If they work together, in how many days will the work be completed?', 'Working together, they complete the work in **6 days**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00090', 'gate-engineering-bank', 'General Aptitude', 1, 26, 'A train 150 m long crosses a platform 250 m long in 20 seconds. What is the speed of the train in km/h?', 'The speed is **72 km/h**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00091', 'gate-engineering-bank', 'General Aptitude', 1, 27, 'A boat travels 24 km downstream in 2 hours and the same distance upstream in 3 hours. What is the speed of the boat in still water?', 'The speed of the boat in still water is **10 km/h**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00092', 'gate-engineering-bank', 'General Aptitude', 1, 28, 'The average of 5 consecutive even numbers is 24. What is the largest of these numbers?', 'The largest number is **28**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00093', 'gate-engineering-bank', 'General Aptitude', 1, 29, 'The average weight of 8 persons increases by 2.5 kg when a new person replaces one weighing 65 kg. What is the weight of the new person?', 'The weight of the new person is **85 kg**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00094', 'gate-engineering-bank', 'General Aptitude', 1, 30, 'In what ratio must a shopkeeper mix two varieties of rice costing ₹30/kg and ₹45/kg to get a mixture worth ₹36/kg?', 'The required ratio is **3:2**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00095', 'gate-engineering-bank', 'General Aptitude', 1, 31, 'If x : y = 3 : 4 and y : z = 8 : 9, what is x : y : z?', 'The combined ratio is **6 : 8 : 9**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00096', 'gate-engineering-bank', 'General Aptitude', 1, 32, 'A alone can do a piece of work in 20 days, B alone in 30 days. They start together, but A leaves after 5 days. In how many more days will B finish the remaining work?', 'B will take **17.5 more days** to finish the remaining work.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00097', 'gate-engineering-bank', 'General Aptitude', 1, 33, 'What is the probability of getting a sum of 7 when two fair dice are rolled?', 'The probability is **1/6**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00098', 'gate-engineering-bank', 'General Aptitude', 1, 34, 'From a deck of 52 cards, one card is drawn at random. What is the probability that it is either a king or a heart?', 'The probability is **4/13**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00099', 'gate-engineering-bank', 'General Aptitude', 1, 35, 'In how many ways can the letters of the word ''LEADER'' be arranged?', 'The letters can be arranged in **360 ways**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00100', 'gate-engineering-bank', 'General Aptitude', 1, 36, 'What is the next number in the series: 2, 6, 12, 20, 30, ___?', 'The next number is **42**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00101', 'gate-engineering-bank', 'General Aptitude', 1, 37, 'Find the missing number in the series: 5, 11, 23, 47, ___?', 'The missing number is **95**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00102', 'gate-engineering-bank', 'General Aptitude', 1, 38, 'If the sum of three consecutive integers is 72, what is the smallest integer?', 'The smallest integer is **23**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00103', 'gate-engineering-bank', 'General Aptitude', 1, 39, 'A sum is divided among A, B, and C in the ratio 2:3:5. If C gets ₹3000 more than A, what is the total sum?', 'The total sum is **₹10,000**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00104', 'gate-engineering-bank', 'General Aptitude', 1, 40, 'A car covers a certain distance at 60 km/h and returns the same distance at 40 km/h. What is the average speed for the entire round trip?', 'The average speed is **48 km/h**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00105', 'gate-engineering-bank', 'General Aptitude', 1, 41, 'What is the compound interest on ₹5,000 for 1 year at 10% per annum, compounded half-yearly?', 'The compound interest is **₹512.50**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00106', 'gate-engineering-bank', 'General Aptitude', 1, 42, 'A bar chart shows a company''s profits (in ₹ lakh) over 4 years as 20, 25, 30, 45. What is the percentage increase in profit from year 3 to year 4?', 'The percentage increase is **50%**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00107', 'gate-engineering-bank', 'General Aptitude', 1, 43, 'A pie chart shows that a family spends 25% of its income on rent, 20% on food, 15% on education, and the rest on other expenses. If the monthly income is ₹40,000, how much is spent on ''other expenses''?', 'The amount spent on other expenses is **₹16,000**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00108', 'gate-engineering-bank', 'General Aptitude', 1, 44, 'If a cube is painted on all its faces and then cut into 27 smaller equal cubes, how many smaller cubes have exactly two faces painted?', '**12** smaller cubes have exactly two painted faces.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00109', 'gate-engineering-bank', 'General Aptitude', 1, 45, 'In a 3x3x3 cube painted on all faces and cut into 27 unit cubes, how many unit cubes have no face painted at all?', '**1** unit cube has no face painted.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00110', 'gate-engineering-bank', 'General Aptitude', 1, 46, 'A square sheet of paper is folded in half twice and then a small triangle is cut from the folded corner. When unfolded, how many holes appear in the sheet?', '**4 holes** appear when unfolded.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00111', 'gate-engineering-bank', 'General Aptitude', 1, 47, 'If the mirror image of the time 3:40 is viewed in a standard analog clock mirror, what time does it show?', 'The mirror image shows **8:20**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00112', 'gate-engineering-bank', 'General Aptitude', 1, 48, 'A solid cube is viewed from the top, front, and side to produce three 2D projections. What is this technique called in spatial aptitude and engineering drawing?', 'This is called **orthographic projection**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00113', 'gate-engineering-bank', 'General Aptitude', 1, 49, 'Statement: ''If it rains, the match will be cancelled.'' Given that the match was NOT cancelled, what can be logically inferred about the weather?', 'It can be inferred that **it did not rain**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00114', 'gate-engineering-bank', 'General Aptitude', 1, 50, 'Statement: ''All squares are rectangles.'' Is the converse ''All rectangles are squares'' necessarily true?', '**No**, the converse is not necessarily true.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00115', 'gate-engineering-bank', 'General Aptitude', 1, 51, 'Choose the correct sentence: ''The data was analyzed carefully'' or ''The data were analyzed carefully'' (in formal/technical usage)?', 'In **formal and technical/scientific usage**, ''data'' is treated as a plural noun (plural of ''datum''), so the grammatically preferred sentence is **''The data were analyzed carefully.''**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00116', 'gate-engineering-bank', 'General Aptitude', 1, 52, 'What is the correct past participle of the verb ''to lie'' (in the sense of reclining, not telling an untruth)?', 'The past participle is **''lain''** (lie → lay → lain), referring to reclining.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00117', 'gate-engineering-bank', 'General Aptitude', 1, 53, 'Identify the figure of speech in the sentence: ''The classroom was a zoo during the fire drill.''', 'This is an example of a **metaphor**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00118', 'gate-engineering-bank', 'General Aptitude', 1, 54, 'Choose the correctly punctuated sentence: ''Lets eat, Grandma'' vs ''Let''s eat, Grandma.''', 'The correctly punctuated sentence is **''Let''s eat, Grandma.''**
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00119', 'gate-engineering-bank', 'General Aptitude', 1, 55, 'A problem states: ''If 6 workers can build a wall in 10 days, how many workers are needed to build the same wall in 4 days (assuming equal work rate per worker)?''', '**15 workers** are needed.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00120', 'gate-engineering-bank', 'General Aptitude', 1, 56, 'A man walks at a speed of 5 km/h and reaches his office 6 minutes late. If he walks at 6 km/h, he reaches 2 minutes early. What is the distance to his office?', 'The distance is **4 km**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00121', 'gate-engineering-bank', 'General Aptitude', 1, 57, 'What logical fallacy is committed in the argument: ''Most successful entrepreneurs dropped out of college, so dropping out of college leads to success''?', 'This commits the **correlation-causation fallacy** (also related to survivorship bias).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00122', 'gate-engineering-bank', 'General Aptitude', 1, 58, 'In a row of children facing north, Rohan is 7th from the left and 12th from the right. How many children are there in total?', 'There are **18 children** in total.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00123', 'gate-engineering-bank', 'General Aptitude', 1, 59, 'Pointing to a photograph, a man says, ''She is the daughter of my grandfather''s only son.'' How is the woman related to the man?', 'The woman is the man''s **sister**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00124', 'gate-engineering-bank', 'General Aptitude', 1, 60, 'If South-East becomes North, North-East becomes West, then what does South become under the same transformation?', 'South becomes **East**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00125', 'gate-engineering-bank', 'General Aptitude', 1, 61, 'A person walks 10 m north, then turns right and walks 10 m, then turns right again and walks 10 m. How far is he from his starting point and in which direction?', 'He is **10 m to the east** of his starting point.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00126', 'gate-engineering-bank', 'General Aptitude', 1, 62, 'A number when divided by 357 gives a remainder of 39. What remainder will be obtained when the same number is divided by 17?', 'The remainder is **5**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00127', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 0, 'What is the worst-case time complexity of searching an element in an unsorted array, and how does binary search improve on this for a sorted array?', 'Searching an unsorted array takes `O(n)` time in the worst case (linear search).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00128', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 1, 'Compare the time complexity of insertion at the beginning of an array versus a singly linked list.', 'Inserting at the beginning of an **array** takes `O(n)` time, since all existing elements must be shifted one position to the right.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00129', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 2, 'What is the time complexity of accessing the i-th element in an array versus a singly linked list?', 'Array access by index is **`O(1)`**, since the address can be computed directly as `base + i × element_size`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00130', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 3, 'What are the time complexities of push and pop operations on a stack implemented using an array?', 'Both **push** and **pop** operations on an array-based stack take `O(1)` time (amortized `O(1)` if the array needs occasional resizing), since elements are added/removed only from the top.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00131', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 4, 'How is a queue different from a stack in terms of the order of element removal?', 'A **stack** follows **LIFO** (Last In, First Out) order — the most recently inserted element is removed first.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00132', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 5, 'What is a circular queue, and why is it preferred over a simple linear queue implemented using an array?', 'A **circular queue** treats the underlying array as circular, wrapping the rear pointer back to index 0 after reaching the end.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00133', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 6, 'What is the worst-case height of a Binary Search Tree (BST) with n nodes, and when does this occur?', 'The worst-case height of a BST with `n` nodes is `O(n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00134', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 7, 'What property must a self-balancing tree like an AVL tree maintain, and what is the resulting worst-case height?', 'An **AVL tree** maintains the balance condition that for every node, the **heights of the left and right subtrees differ by at most 1**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00135', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 8, 'What is the time complexity of search, insert, and delete operations in a balanced Binary Search Tree versus a hash table (average case)?', 'In a **balanced BST**, search, insert, and delete all take `O(log n)` time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00136', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 9, 'What is a min-heap, and what is the time complexity of extracting the minimum element?', 'A **min-heap** is a complete binary tree where every parent node''s value is **less than or equal to** both its children''s values.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00137', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 10, 'What is the time complexity of building a heap from an unsorted array of n elements using the bottom-up heapify method?', 'Building a heap bottom-up takes **`O(n)` time**, not `O(n log n)` as a naive analysis might suggest.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00138', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 11, 'Explain how Heapsort works and state its time complexity.', '**Heapsort** first builds a max-heap from the array in `O(n)` time, then repeatedly extracts the maximum element (swapping it to the end and sifting down) `n` times, each taking `O(log n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00139', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 12, 'What is the average-case and worst-case time complexity of Quicksort, and when does the worst case occur?', 'Quicksort''s **average-case** time complexity is `O(n log n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00140', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 13, 'Is Merge Sort a stable sorting algorithm? What is its time and space complexity?', 'Yes, **Merge Sort is stable** (preserves the relative order of equal elements), when implemented to prefer the left sub-array element during merging on ties.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00141', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 14, 'What is the time complexity of Bubble Sort in the best case, and under what condition is this best case achieved?', 'Bubble Sort''s best-case time complexity is `O(n)`, achieved when the array is **already sorted**, provided the implementation includes an **early-termination flag** that stops if no swaps occur in a full pass.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00142', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 15, 'Compare the time complexity of Insertion Sort for nearly-sorted data versus completely reverse-sorted data.', 'For **nearly-sorted** data, Insertion Sort performs close to `O(n)`, since each element requires only a few shifts to reach its correct position.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00143', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 16, 'Which comparison-based sorting algorithms achieve the lower bound of O(n log n) for sorting n elements, and why can no comparison sort do better?', '**Merge Sort, Heapsort,** and (on average) **Quicksort** achieve `O(n log n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00144', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 17, 'What non-comparison sorting algorithm can sort n integers in O(n+k) time, where k is the range of input values?', '**Counting Sort** achieves `O(n + k)` time, where `k` is the range of possible integer values.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00145', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 18, 'What is Radix Sort, and what is its overall time complexity when sorting n d-digit numbers?', '**Radix Sort** sorts numbers digit by digit, from the least significant to the most significant digit, using a **stable sort** (typically Counting Sort) as a subroutine for each digit.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00146', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 19, 'What is the time complexity of Breadth-First Search (BFS) and Depth-First Search (DFS) on a graph with V vertices and E edges?', 'Both **BFS and DFS** run in `O(V + E)` time when the graph is represented using an **adjacency list**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00147', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 20, 'What data structure is used to implement BFS, and what role does it play in the traversal?', 'BFS uses a **queue** to maintain the FIFO order of vertex visitation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00148', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 21, 'What is the time complexity of Dijkstra''s algorithm using a binary min-heap for finding single-source shortest paths?', 'Using a **binary min-heap** (priority queue), Dijkstra''s algorithm runs in `O((V + E) log V)` time, since each of the `E` edge relaxations may require an `O(log V)` heap operation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00149', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 22, 'Why does Dijkstra''s algorithm fail to work correctly in the presence of negative edge weights, and which algorithm handles this case?', 'Dijkstra''s algorithm assumes that once a vertex''s shortest distance is finalized, it cannot be improved later — a greedy assumption that **negative edge weights violate**, since a later path through a negative edge could still yield a shorter distance.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00150', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 23, 'How does the Bellman-Ford algorithm detect the presence of a negative-weight cycle in a graph?', 'After performing `V−1` rounds of edge relaxation, Bellman-Ford performs **one additional relaxation pass**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00151', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 24, 'What is the time complexity of the Floyd-Warshall algorithm for computing all-pairs shortest paths, and what is its space complexity?', 'The **Floyd-Warshall algorithm** runs in `O(V^3)` time and uses `O(V^2)` space, computing shortest paths between **every pair of vertices** using dynamic programming over intermediate vertices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00152', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 25, 'Compare the time complexities of Kruskal''s and Prim''s algorithms for finding a Minimum Spanning Tree.', '**Kruskal''s algorithm** runs in `O(E log E)` time, dominated by sorting the edges, and uses a **Disjoint Set Union (Union-Find)** structure to detect cycles.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00153', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 26, 'Under what condition does Kruskal''s algorithm add an edge to the growing Minimum Spanning Tree?', 'Kruskal''s algorithm processes edges in **increasing order of weight** and adds an edge to the MST **only if it does not form a cycle** with the edges already selected.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00154', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 27, 'What is topological sorting, and on what type of graph can it be performed?', 'A **topological sort** is a linear ordering of vertices such that for every directed edge `u → v`, `u` appears **before** `v` in the ordering.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00155', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 28, 'What is the time complexity of topological sort using DFS, and how is the ordering extracted from the DFS traversal?', 'Topological sort via DFS takes `O(V + E)` time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00156', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 29, 'Define the time complexity notations Big-O, Big-Omega, and Big-Theta and what each represents.', '`O(g(n))` gives an **asymptotic upper bound** on the growth rate of a function (worst-case behavior).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00157', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 30, 'Using the Master Theorem, what is the time complexity of a recurrence T(n) = 2T(n/2) + O(n)?', 'The time complexity is `O(n log n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00158', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 31, 'Using the Master Theorem, what is the time complexity of the recurrence T(n) = 2T(n/2) + O(1)?', 'The time complexity is `O(n)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00159', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 32, 'What is the recurrence relation for Binary Search, and what is its resulting time complexity?', 'The recurrence is `T(n) = T(n/2) + O(1)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00160', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 33, 'What is the key difference between the Divide and Conquer and Dynamic Programming algorithmic paradigms?', '**Divide and Conquer** splits a problem into **independent** subproblems, solves each separately, and combines the results (e.g., Merge Sort).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00161', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 34, 'What is the time complexity of the dynamic programming solution to the 0/1 Knapsack problem with n items and capacity W?', 'The DP solution to the 0/1 Knapsack problem runs in `O(n × W)` time and `O(n × W)` space (reducible to `O(W)` space with a 1D array).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00162', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 35, 'What is the time complexity of computing the nth Fibonacci number using naive recursion versus dynamic programming (memoization)?', 'Naive recursive Fibonacci takes **exponential** time, `O(2^n)` (more precisely `O(φ^n)` where `φ` is the golden ratio), due to repeated recomputation of the same subproblems.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00163', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 36, 'What is the time complexity of finding the Longest Common Subsequence (LCS) of two strings of lengths m and n using dynamic programming?', 'The DP solution for LCS runs in **`O(m × n)` time and `O(m × n)` space** (reducible to `O(min(m,n))` space if only the length, not the subsequence itself, is needed), using a 2D table where `dp[i][j]` represents the LCS length of the first `i` and `j` characters of the two strings.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00164', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 37, 'What greedy strategy does the activity selection problem use, and what is its time complexity?', 'The **activity selection problem** is solved greedily by sorting activities by their **finish time** and always selecting the next activity whose start time is **after** the finish time of the last selected activity.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00165', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 38, 'What is the difference between a greedy algorithm and dynamic programming in terms of making choices?', 'A **greedy algorithm** makes a **locally optimal choice at each step**, without reconsidering previous decisions, and works correctly only when the problem has the **greedy-choice property** and **optimal substructure**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00166', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 39, 'What is the significance of ''optimal substructure'' and ''overlapping subproblems'' for applying dynamic programming?', '**Optimal substructure** means an optimal solution to the problem can be constructed from **optimal solutions of its subproblems**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00167', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 40, 'What is backtracking, and how does it differ from brute-force exhaustive search?', '**Backtracking** incrementally builds candidate solutions and **abandons (prunes)** a partial solution as soon as it determines that it cannot possibly lead to a valid complete solution.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00168', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 41, 'What is the time complexity of the N-Queens problem solved via backtracking, in terms of its worst-case behavior?', 'The N-Queens backtracking solution has a worst-case time complexity of roughly **`O(N!)`**, since at each row there are progressively fewer safe column choices, but pruning invalid placements early makes it far faster in practice than the naive `O(N^N)` brute-force approach of trying every queen placement independently.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00169', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 42, 'Define P, NP, NP-hard, and NP-complete complexity classes.', '**P** is the class of problems solvable in **polynomial time** by a deterministic algorithm.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00170', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 43, 'Is the question ''Is P equal to NP?'' resolved, and what would it imply if P = NP?', '**No**, whether `P = NP` remains one of the most famous **unsolved problems** in computer science (a Millennium Prize Problem).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00171', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 44, 'Name two classic NP-complete problems commonly referenced in GATE.', 'Two classic NP-complete problems are the **Boolean Satisfiability Problem (SAT)** — the first problem proven NP-complete (Cook-Levin theorem) — and the **Traveling Salesman Problem (decision version)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00172', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 45, 'What is a self-balancing B-Tree primarily used for, and why is it preferred over a BST for disk-based storage?', '**B-Trees** are primarily used in **databases and file systems** for indexing large datasets stored on disk.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00173', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 46, 'What is the difference between a B-Tree and a B+ Tree, particularly regarding where data records are stored?', 'In a **B-Tree**, data records can be stored in **both internal and leaf nodes**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00174', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 47, 'What is a hash collision, and name two common techniques to resolve it.', 'A **hash collision** occurs when two distinct keys map to the **same hash index/bucket**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00175', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 48, 'What is the load factor of a hash table, and how does it affect performance?', 'The **load factor** is defined as `α = n/m`, where `n` is the number of stored elements and `m` is the number of buckets (table size).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00176', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 49, 'What is the amortized time complexity of a sequence of n insertions into a dynamic array (like a resizable vector) that doubles in size when full?', 'The amortized time per insertion is `O(1)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00177', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 50, 'What is a doubly linked list, and what operation does it support more efficiently than a singly linked list?', 'A **doubly linked list** has nodes containing pointers to both the **next and previous** nodes.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00178', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 51, 'How is a priority queue typically implemented to achieve O(log n) insertion and O(log n) extraction of the minimum/maximum element?', 'A priority queue is typically implemented using a **binary heap** (min-heap or max-heap).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00179', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 52, 'What is the difference between a complete binary tree and a full binary tree?', 'A **full binary tree** is one where every node has either **0 or 2 children** (no node has exactly 1 child).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00180', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 53, 'In an array representation of a complete binary tree (0-indexed), how are the parent and children of a node at index i located?', 'For a node at index `i` (0-indexed array), the **left child** is at index `2i+1`, the **right child** is at index `2i+2`, and the **parent** is at index `floor((i−1)/2)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00181', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 54, 'What is an inorder traversal of a Binary Search Tree guaranteed to produce?', 'An **inorder traversal** (left subtree → node → right subtree) of a BST always produces the elements in **sorted (ascending) order**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00182', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 55, 'What three traversal orders exist for a binary tree, and how do they differ in the order of visiting the root?', '**Preorder** visits root → left subtree → right subtree.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00183', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 56, 'What is a Trie (prefix tree), and for what kind of operation is it especially efficient?', 'A **Trie** is a tree-based data structure that stores strings by sharing common prefixes along root-to-node paths, where each node typically represents a character.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00184', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 57, 'What is the space complexity of an adjacency matrix versus an adjacency list for representing a graph with V vertices and E edges?', 'An **adjacency matrix** requires `O(V^2)` space, regardless of the number of edges.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00185', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 58, 'What is the time complexity of detecting a cycle in a directed graph using DFS?', 'Cycle detection in a directed graph using DFS takes `O(V + E)` time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00186', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 59, 'What is the difference between a stable and an unstable sorting algorithm, giving one example of each.', 'A **stable** sorting algorithm preserves the **relative order of equal-keyed elements** from the input in the output (e.g., **Merge Sort** or **Insertion Sort**).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00187', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 60, 'What is the time complexity of the Knuth-Morris-Pratt (KMP) string matching algorithm, and what preprocessing does it use to achieve this?', 'KMP runs in `O(n + m)` time, where `n` is the text length and `m` is the pattern length.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00188', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 61, 'What is a recursive algorithm''s call stack space complexity for computing factorial(n) using simple recursion, and how can it be improved?', 'Simple recursive `factorial(n)` uses `O(n)` auxiliary stack space, since each recursive call adds a new stack frame until the base case is reached.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00189', 'gate-engineering-bank', 'Computer Science — Data Structures & Algorithms', 2, 62, 'How is the kth largest element in an array found efficiently using a heap, and what is the resulting time complexity?', 'To find the **kth largest** element efficiently, maintain a **min-heap of size k** while scanning the array, replacing the root whenever a larger element is found and the heap already has `k` elements.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00190', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 0, 'What are the typical states in a process life cycle, and what does each represent?', 'The typical process states are **New, Ready, Running, Waiting (Blocked), and Terminated**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00191', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 1, 'What is the difference between a process and a thread?', 'A **process** is an independent program in execution with its own separate **address space, memory, and resources**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00192', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 2, 'What is stored in a Process Control Block (PCB)?', 'A **PCB** stores all information needed to manage a process, including the **process state, program counter, CPU registers, CPU scheduling information, memory management information, and I/O status information**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00193', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 3, 'Compare the average waiting time characteristics of FCFS and SJF (Shortest Job First) scheduling.', '**FCFS (First Come First Served)** can lead to high average waiting time due to the **convoy effect**, where short processes get stuck behind a long one.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00194', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 4, 'What is the Round Robin scheduling algorithm, and how does the time quantum size affect its performance?', '**Round Robin** assigns each process a fixed **time quantum**, cycling through the ready queue and preempting a process once its quantum expires.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00195', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 5, 'What is the key difference between preemptive and non-preemptive scheduling, with an example of each?', '**Preemptive scheduling** allows the OS to **forcibly remove the CPU** from a running process (e.g., **Round Robin, Preemptive SJF/Priority**).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00196', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 6, 'What is priority inversion, and how is it typically resolved?', '**Priority inversion** occurs when a **lower-priority process holds a resource** needed by a higher-priority process, while a **medium-priority process** preempts the lower-priority one, indirectly delaying the high-priority process further.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00197', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 7, 'What is a race condition, and what programming construct is used to prevent it?', 'A **race condition** occurs when multiple processes/threads access and modify **shared data concurrently**, and the final outcome depends on the unpredictable **timing/order of execution**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00198', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 8, 'State the four necessary conditions for a deadlock to occur (Coffman conditions).', 'The four necessary conditions are: **Mutual Exclusion** (resources cannot be shared), **Hold and Wait** (a process holds resources while waiting for more), **No Preemption** (resources cannot be forcibly taken away), and **Circular Wait** (a cycle of processes each waiting for a resource held by the next).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00199', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 9, 'What is the purpose of the Banker''s Algorithm, and what does it require as input?', 'The **Banker''s Algorithm** is a **deadlock avoidance** algorithm that checks whether granting a resource request would leave the system in a **safe state** (where all processes can eventually complete).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00200', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 10, 'What is the difference between deadlock prevention and deadlock avoidance?', '**Deadlock prevention** works by ensuring that at least one of the four necessary conditions for deadlock **can never hold** (a static, structural guarantee).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00201', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 11, 'What is a binary semaphore, and how does it differ from a counting semaphore?', 'A **binary semaphore** takes only values 0 or 1, functioning similarly to a **mutex lock** for mutual exclusion.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00202', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 12, 'What synchronization problem does the Producer-Consumer problem illustrate, and how is it typically solved?', 'The **Producer-Consumer (bounded buffer) problem** illustrates the need to coordinate producers adding items to a shared, finite buffer and consumers removing them, without **overflow, underflow, or race conditions**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00203', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 13, 'What does the Dining Philosophers problem illustrate, and what is one common solution to avoid deadlock in it?', 'The **Dining Philosophers problem** illustrates challenges in **resource allocation and avoiding deadlock/starvation** among concurrent processes competing for shared resources (forks).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00204', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 14, 'What is virtual memory, and what key benefit does it provide?', '**Virtual memory** is a memory management technique that gives each process the illusion of a **large, contiguous address space**, independent of the actual physical (main) memory available.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00205', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 15, 'What is paging, and what problem does it solve compared to variable-sized partitioning?', '**Paging** divides both logical and physical memory into fixed-size blocks — **pages** (logical) and **frames** (physical) — eliminating the need for contiguous memory allocation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00206', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 16, 'What is the function of a Translation Lookaside Buffer (TLB) in a paging system?', 'A **TLB** is a small, fast **cache** that stores recent **virtual-to-physical address translations** (page table entries).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00207', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 17, 'What is a page fault, and what sequence of actions does the OS take when one occurs?', 'A **page fault** occurs when a process accesses a page that is **not currently present in physical memory**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00208', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 18, 'Compare the FIFO, LRU, and Optimal page replacement algorithms in terms of performance.', '**FIFO** replaces the oldest-loaded page and can suffer from **Belady''s anomaly** (more frames causing more page faults).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00209', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 19, 'What is Belady''s Anomaly?', '**Belady''s Anomaly** refers to the counter-intuitive situation where **increasing the number of page frames** available to a process **increases the number of page faults**, rather than decreasing it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00210', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 20, 'What is thrashing, and under what condition does it typically occur?', '**Thrashing** occurs when a system spends **more time swapping pages in and out of memory than executing actual processes**, causing CPU utilization to drop sharply.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00211', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 21, 'What is the difference between internal fragmentation and external fragmentation in memory management?', '**Internal fragmentation** occurs when allocated memory is slightly larger than requested, wasting space **within** an allocated block/page (common in fixed-size paging).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00212', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 22, 'What is segmentation, and how does it differ conceptually from paging?', '**Segmentation** divides a process''s logical address space into **variable-sized, logically meaningful units** (segments like code, stack, heap), each with a base and limit, as opposed to paging''s **fixed-size, physically motivated** division.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00213', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 23, 'What is the working set model used for in memory management?', 'The **working set model** defines the set of pages a process has referenced in its most recent `Δ` (delta) memory references.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00214', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 24, 'Compare the FCFS, SSTF, and SCAN disk scheduling algorithms in terms of seek time optimization.', '**FCFS** services requests in arrival order, often leading to **high average seek time** due to erratic head movement.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00215', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 25, 'What is the key difference between the SCAN and C-SCAN (Circular SCAN) disk scheduling algorithms?', '**SCAN** moves the disk head back and forth across the disk, servicing requests in both directions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00216', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 26, 'What is the role of a kernel in an operating system, and what distinguishes monolithic from microkernel architectures?', 'The **kernel** is the core component of the OS that manages hardware resources, process scheduling, memory, and I/O, mediating between applications and hardware.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00217', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 27, 'What is the difference between a system call and a library function call?', 'A **system call** is a request made by a program to the **operating system kernel** for a privileged service (e.g., file I/O, process creation), requiring a **mode switch from user mode to kernel mode**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00218', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 28, 'What is a context switch, and why does it introduce overhead?', 'A **context switch** is the process of saving the state (registers, program counter, memory maps) of a currently running process/thread and loading the state of another, allowing the CPU to switch between them.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00219', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 29, 'What is a super key, candidate key, primary key, and foreign key in the relational model?', 'A **super key** is any set of attributes that uniquely identifies a tuple. A **candidate key** is a **minimal super key** (no proper subset is also a super key).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00220', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 30, 'What is a functional dependency, and how is it denoted?', 'A **functional dependency** `X → Y` means that the value of attribute set `X` **uniquely determines** the value of attribute set `Y` — for any two tuples with the same `X` value, they must also have the same `Y` value.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00221', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 31, 'What condition must a relation satisfy to be in First Normal Form (1NF)?', 'A relation is in **1NF** if every attribute contains only **atomic (indivisible) values**, and there are **no repeating groups or multi-valued attributes** within a single column.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00222', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 32, 'What is a partial dependency, and how does Second Normal Form (2NF) address it?', 'A **partial dependency** occurs when a **non-prime attribute depends on only part of a composite candidate key**, rather than the whole key.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00223', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 33, 'What is a transitive dependency, and how does Third Normal Form (3NF) address it?', 'A **transitive dependency** exists when a non-prime attribute depends on another non-prime attribute, rather than directly on the candidate key (i.e., `X → Y → Z` where `X` is the key and `Y, Z` are non-prime).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00224', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 34, 'What is Boyce-Codd Normal Form (BCNF), and how does it differ from 3NF?', 'A relation is in **BCNF** if, for every non-trivial functional dependency `X → Y`, `X` must be a **super key**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00225', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 35, 'What are the ACID properties of a database transaction?', '**Atomicity**: a transaction executes completely or not at all.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00226', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 36, 'What is the difference between a shared (read) lock and an exclusive (write) lock in concurrency control?', 'A **shared lock (S-lock)** allows multiple transactions to **read** the same data item concurrently, but prevents any transaction from writing to it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00227', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 37, 'What is Two-Phase Locking (2PL), and what guarantee does it provide?', '**Two-Phase Locking** requires every transaction to have a **growing phase** (acquiring locks, no releases) followed by a **shrinking phase** (releasing locks, no further acquisitions), with no overlap.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00228', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 38, 'What problem does Strict Two-Phase Locking solve beyond basic Two-Phase Locking?', '**Strict 2PL** requires that all **exclusive (write) locks** be held until the transaction **commits or aborts**, rather than being released during the shrinking phase.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00229', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 39, 'What is a deadlock in the context of database transactions, and how can timestamp ordering avoid it entirely?', 'A transaction **deadlock** occurs when two or more transactions are each waiting for a lock held by the other, forming a cycle with no progress possible.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00230', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 40, 'What is the difference between conflict serializability and view serializability of a schedule?', 'A schedule is **conflict serializable** if it can be transformed into a serial schedule by swapping **non-conflicting** (non-adjacent-dependent) operations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00231', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 41, 'What is the purpose of the E-R (Entity-Relationship) model, and what are its three core components?', 'The **E-R model** is a high-level conceptual data model used to design a database schema before implementation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00232', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 42, 'What is the difference between a weak entity and a strong entity in the E-R model?', 'A **strong entity** has its own **primary key** and can be uniquely identified independently.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00233', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 43, 'What is the cardinality ratio in a relationship, and name the four common types.', 'The **cardinality ratio** describes the maximum number of relationship instances an entity can participate in.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00234', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 44, 'What is the difference between an INNER JOIN and a LEFT OUTER JOIN in SQL?', 'An **INNER JOIN** returns only the rows where there is a **matching value in both tables** being joined.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00235', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 45, 'What is the difference between the SQL commands DELETE, TRUNCATE, and DROP?', '**DELETE** removes specific rows (optionally filtered by a `WHERE` clause) and can be rolled back; it''s a DML command that fires triggers and logs each row individually.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00236', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 46, 'What is the purpose of the GROUP BY clause in SQL, and how does HAVING differ from WHERE in this context?', '**GROUP BY** groups rows sharing the same values in specified columns, typically used with **aggregate functions** (`COUNT`, `SUM`, `AVG`, etc.).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00237', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 47, 'What is a database index, and what is the typical underlying data structure used to implement it?', 'A **database index** is an auxiliary data structure that speeds up data retrieval operations on a table, at the cost of additional storage space and slower writes (since the index must also be updated).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00238', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 48, 'What is the difference between a clustered index and a non-clustered index?', 'A **clustered index** determines the **physical storage order** of data rows in the table, so a table can have **only one** clustered index.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00239', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 49, 'What does the term ''lossless join decomposition'' mean in the context of normalization?', 'A decomposition of relation `R` into `R1` and `R2` is **lossless** if joining `R1` and `R2` back together (natural join) reproduces **exactly the original relation `R`**, with no spurious tuples introduced and no information lost.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00240', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 50, 'What is a multivalued dependency, and which normal form addresses it?', 'A **multivalued dependency** `X ↠ Y` exists when the set of `Y` values associated with a given `X` value is **independent of all other attributes** in the relation, often causing undesirable data redundancy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00241', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 51, 'What is the purpose of database normalization, and what is its main tradeoff?', '**Normalization** organizes relations to **minimize data redundancy** and avoid **update, insertion, and deletion anomalies** by decomposing tables based on functional dependencies.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00242', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 52, 'What is a correlated subquery in SQL, and how does its execution differ from a simple (uncorrelated) subquery?', 'A **correlated subquery** references a column from the **outer query**, so it must be **re-evaluated once for every row** processed by the outer query.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00243', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 53, 'What is the difference between UNION and UNION ALL in SQL?', '**UNION** combines the result sets of two queries and **removes duplicate rows**, which requires an implicit sort/distinct operation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00244', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 54, 'What is a trigger in a database, and when is it typically invoked?', 'A **trigger** is a stored procedure that automatically executes in response to a specific event — such as an `INSERT`, `UPDATE`, or `DELETE` — on a specified table.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00245', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 55, 'What is referential integrity, and how is it typically enforced in a relational database?', '**Referential integrity** ensures that a foreign key value in one table always corresponds to an **existing primary key value** in the referenced table (or is `NULL`, if allowed).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00246', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 56, 'What is the difference between optimistic and pessimistic concurrency control?', '**Pessimistic concurrency control** assumes conflicts are likely and uses **locks** to prevent transactions from interfering with each other proactively (blocking access until it''s safe).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00247', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 57, 'What is a checkpoint in database recovery management, and why is it useful?', 'A **checkpoint** is a point at which the database system writes all its buffered (modified) data and transaction log records to stable storage, recording this point in the log.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00248', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 58, 'What are the differences between the WAIT-DIE and WOUND-WAIT deadlock prevention schemes based on timestamps?', 'In **WAIT-DIE**, an **older** transaction is allowed to wait for a resource held by a **younger** transaction, but a younger transaction requesting a resource held by an older one is **aborted (dies)** and restarted.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00249', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 59, 'What is the difference between physical and logical data independence?', '**Physical data independence** is the ability to change the **physical storage structure** (e.g., file organization, indexes) without needing to change the conceptual or application-level schema.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00250', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 60, 'What is the difference between a mutex and a semaphore in operating systems?', 'A **mutex** is a locking mechanism specifically for **mutual exclusion**, typically allowing only the thread that locked it to unlock it, used to protect a single critical section.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00251', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 61, 'What does the term ''starvation'' mean in the context of process scheduling, and which scheduling policy is particularly prone to it?', '**Starvation** occurs when a process is **perpetually denied the resources (CPU time)** it needs to proceed, typically because other processes are repeatedly favored.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00252', 'gate-engineering-bank', 'Computer Science — Operating Systems & DBMS', 3, 62, 'What is the difference between logical (virtual) address space and physical address space?', 'The **logical address space** is the set of addresses a process generates and references during execution, as seen by the CPU before translation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00253', 'gate-engineering-bank', 'Computer Networks', 4, 0, 'What are the seven layers of the OSI model, from bottom to top?', 'From bottom to top: **Physical, Data Link, Network, Transport, Session, Presentation, and Application** layers.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00254', 'gate-engineering-bank', 'Computer Networks', 4, 1, 'How does the TCP/IP model differ from the OSI model in terms of number of layers?', 'The **TCP/IP model** has **4 layers**: Network Interface (Link), Internet, Transport, and Application.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00255', 'gate-engineering-bank', 'Computer Networks', 4, 2, 'What is the Nyquist theorem''s formula for the maximum data rate of a noiseless channel?', 'The **Nyquist formula** is `C = 2B log2(L)`, where `B` is the channel bandwidth and `L` is the number of discrete signal levels.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00256', 'gate-engineering-bank', 'Computer Networks', 4, 3, 'State Shannon''s channel capacity theorem and its formula.', '**Shannon''s theorem** gives the maximum data rate (**channel capacity**) of a channel in the presence of noise: `C = B log2(1 + S/N)`, where `B` is bandwidth and `S/N` is the **signal-to-noise ratio**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00257', 'gate-engineering-bank', 'Computer Networks', 4, 4, 'What is the purpose of a Cyclic Redundancy Check (CRC) in the data link layer?', '**CRC** is an error-detection technique that appends a **remainder bits sequence**, computed by dividing the data (treated as a polynomial) by a fixed generator polynomial, to the transmitted frame.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00258', 'gate-engineering-bank', 'Computer Networks', 4, 5, 'What is the difference between error detection and error correction, and which coding scheme is commonly used for single-bit error correction?', '**Error detection** (e.g., parity, checksum, CRC) only identifies **that** an error occurred, without specifying its location.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00259', 'gate-engineering-bank', 'Computer Networks', 4, 6, 'How many redundant (parity) bits are required in a Hamming code to correct a single-bit error in m data bits?', 'The number of parity bits `r` must satisfy `2^r ≥ m + r + 1`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00260', 'gate-engineering-bank', 'Computer Networks', 4, 7, 'What is the stop-and-wait ARQ protocol, and what is its main drawback for high-bandwidth, high-delay links?', '**Stop-and-Wait ARQ** sends one frame and waits for an acknowledgment before sending the next.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00261', 'gate-engineering-bank', 'Computer Networks', 4, 8, 'What is the sliding window protocol, and how does the window size affect channel utilization?', 'The **sliding window protocol** allows a sender to transmit **multiple frames** before requiring an acknowledgment, up to the size of the window, improving throughput over stop-and-wait.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00262', 'gate-engineering-bank', 'Computer Networks', 4, 9, 'Compare Go-Back-N ARQ and Selective Repeat ARQ in terms of retransmission efficiency.', '**Go-Back-N** retransmits **all frames** from the point of error onward upon a timeout or NAK, even if some later frames were received correctly — simpler but less efficient.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00263', 'gate-engineering-bank', 'Computer Networks', 4, 10, 'What is the difference between pure ALOHA and slotted ALOHA in terms of maximum channel utilization?', '**Pure ALOHA** allows stations to transmit at any time, achieving a maximum throughput of about **18.4%** (`1/2e`) of channel capacity due to frequent collisions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00264', 'gate-engineering-bank', 'Computer Networks', 4, 11, 'What does CSMA/CD stand for, and in what type of network is it primarily used?', '**CSMA/CD** stands for **Carrier Sense Multiple Access with Collision Detection**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00265', 'gate-engineering-bank', 'Computer Networks', 4, 12, 'Why is CSMA/CD not used in wireless networks, and what alternative protocol is used instead?', 'CSMA/CD is impractical in wireless networks due to the **hidden terminal problem** and because a wireless transceiver generally **cannot transmit and sense collisions simultaneously** on the same frequency.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00266', 'gate-engineering-bank', 'Computer Networks', 4, 13, 'What is the purpose of subnetting an IP network, and how is the subnet determined using a subnet mask?', '**Subnetting** divides a larger network into smaller, more manageable sub-networks, improving address utilization, security, and routing efficiency.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00267', 'gate-engineering-bank', 'Computer Networks', 4, 14, 'How many usable host addresses are available in a /27 subnet?', 'A `/27` subnet has `32 − 27 = 5` host bits, giving `2^5 = 32` total addresses.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00268', 'gate-engineering-bank', 'Computer Networks', 4, 15, 'What is the purpose of CIDR (Classless Inter-Domain Routing), and how does it improve on classful addressing?', '**CIDR** allows network prefixes of **arbitrary length** (denoted as `/n` notation, e.g., `192.168.1.0/24`), rather than being restricted to the fixed boundaries of classful addressing (Class A/B/C).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00269', 'gate-engineering-bank', 'Computer Networks', 4, 16, 'What is the difference between a distance vector routing algorithm and a link state routing algorithm?', '**Distance vector routing** (e.g., RIP) has each router share its **entire routing table** (distance estimates to all destinations) with only its **immediate neighbors**, converging gradually (and susceptible to the ''count-to-infinity'' problem).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00270', 'gate-engineering-bank', 'Computer Networks', 4, 17, 'What is the ''count to infinity'' problem in distance vector routing, and what technique mitigates it?', 'The **count-to-infinity problem** occurs when a link failure causes routers to repeatedly increment and exchange incorrect distance estimates to an unreachable destination, converging very slowly.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00271', 'gate-engineering-bank', 'Computer Networks', 4, 18, 'What is the maximum segment lifetime (TIME_WAIT state) used for in TCP connection termination?', 'The **TIME_WAIT** state ensures that any **duplicate or delayed segments** from the closed connection are allowed to expire in the network before the same socket pair (IP+port combination) is reused for a new connection.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00272', 'gate-engineering-bank', 'Computer Networks', 4, 19, 'Describe the TCP three-way handshake used to establish a connection.', 'The handshake proceeds as: the client sends a **SYN** segment with an initial sequence number; the server responds with a **SYN-ACK** segment (acknowledging the client''s SYN and sending its own SYN); the client responds with an **ACK**, completing the connection establishment.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00273', 'gate-engineering-bank', 'Computer Networks', 4, 20, 'What is the key difference between TCP and UDP in terms of reliability and connection orientation?', '**TCP** is **connection-oriented** and **reliable**, providing features like acknowledgments, retransmission, flow control, and congestion control (via the 3-way handshake).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00274', 'gate-engineering-bank', 'Computer Networks', 4, 21, 'What is the role of TCP''s sequence and acknowledgment numbers in ensuring reliable, in-order delivery?', 'The **sequence number** indicates the byte offset of the first byte of data in a segment relative to the initial sequence number, allowing the receiver to reorder out-of-sequence segments.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00275', 'gate-engineering-bank', 'Computer Networks', 4, 22, 'What is TCP''s congestion window (cwnd), and what happens to it during the slow start phase?', 'The **congestion window** limits the amount of unacknowledged data a TCP sender can have in flight, based on the sender''s estimate of **network congestion** (as opposed to the receiver''s advertised window, which reflects buffer capacity).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00276', 'gate-engineering-bank', 'Computer Networks', 4, 23, 'What happens to TCP''s congestion window after a packet loss is detected via three duplicate ACKs (fast retransmit), versus via a timeout?', 'After **three duplicate ACKs**, TCP performs **fast retransmit** and halves the congestion window (entering **fast recovery**, growing linearly afterward) — treating this as a sign of mild congestion.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00277', 'gate-engineering-bank', 'Computer Networks', 4, 24, 'What is the role of DNS (Domain Name System), and what type of record maps a hostname to an IPv4 address?', '**DNS** translates human-readable domain names (e.g., `www.example.com`) into numeric **IP addresses** needed for routing on the network, implemented as a distributed, hierarchical database.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00278', 'gate-engineering-bank', 'Computer Networks', 4, 25, 'What is the purpose of the ARP (Address Resolution Protocol)?', '**ARP** resolves a known **IP address** into the corresponding **MAC (physical) address** of a device on the same local network segment.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00279', 'gate-engineering-bank', 'Computer Networks', 4, 26, 'What is the difference between HTTP and HTTPS?', '**HTTP** (Hypertext Transfer Protocol) transmits data **in plaintext**, making it vulnerable to eavesdropping and tampering.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00280', 'gate-engineering-bank', 'Computer Networks', 4, 27, 'What port numbers are used by default for HTTP, HTTPS, FTP (control), SMTP, and DNS?', '**HTTP** uses port **80**, **HTTPS** uses port **443**, **FTP control** uses port **21** (data transfer on port 20), **SMTP** uses port **25**, and **DNS** uses port **53** (typically over UDP, though TCP is used for zone transfers and large responses).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00281', 'gate-engineering-bank', 'Computer Networks', 4, 28, 'What is the difference between circuit switching and packet switching?', '**Circuit switching** reserves a **dedicated, fixed-bandwidth path** for the entire duration of a communication session (e.g., traditional telephone networks), guaranteeing consistent bandwidth but wasting resources during idle periods.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00282', 'gate-engineering-bank', 'Computer Networks', 4, 29, 'What is the difference between a bridge, a switch, a router, and a hub in networking?', 'A **hub** is a simple physical-layer device that broadcasts incoming signals to all other ports without any intelligence.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00283', 'gate-engineering-bank', 'Computer Networks', 4, 30, 'What is the purpose of Network Address Translation (NAT)?', '**NAT** allows multiple devices on a **private network** (using private IP addresses) to share a single **public IP address** when communicating with external networks.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00284', 'gate-engineering-bank', 'Computer Networks', 4, 31, 'What is the difference between symmetric and asymmetric (public-key) encryption?', '**Symmetric encryption** uses the **same secret key** for both encryption and decryption (e.g., AES), making it fast but requiring secure key distribution.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00285', 'gate-engineering-bank', 'Computer Networks', 4, 32, 'What role does a digital certificate play in establishing a secure TLS connection?', 'A **digital certificate**, issued by a trusted **Certificate Authority (CA)**, binds a public key to an identity (such as a domain name).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00286', 'gate-engineering-bank', 'Computer Networks', 4, 33, 'What is the function of a firewall in network security?', 'A **firewall** monitors and controls incoming and outgoing network traffic based on a defined set of **security rules**, acting as a barrier between a trusted internal network and untrusted external networks.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00287', 'gate-engineering-bank', 'Computer Networks', 4, 34, 'What is the difference between IPv4 and IPv6 in terms of address length and total address space?', '**IPv4** uses **32-bit** addresses, providing about `4.3 billion (2^32)` unique addresses.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00288', 'gate-engineering-bank', 'Computer Networks', 4, 35, 'What is fragmentation in the context of the IP layer, and what field helps reassemble fragments at the destination?', '**IP fragmentation** splits a packet larger than the outgoing link''s **Maximum Transmission Unit (MTU)** into smaller fragments for transmission.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00289', 'gate-engineering-bank', 'Computer Networks', 4, 36, 'What is the time to live (TTL) field in an IP header used for?', 'The **TTL field** limits the lifespan of a packet in the network by being **decremented by each router** that forwards it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00290', 'gate-engineering-bank', 'Computer Networks', 4, 37, 'What is the purpose of the ICMP protocol, and name one common utility that relies on it.', '**ICMP (Internet Control Message Protocol)** is used to send **error messages and operational information** about network conditions, such as unreachable destinations or expired TTLs.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00291', 'gate-engineering-bank', 'Computer Networks', 4, 38, 'What is a Virtual Private Network (VPN), and what key security property does it typically provide over a public network?', 'A **VPN** creates a secure, encrypted **tunnel** over a public network (like the internet), allowing remote users or sites to communicate as if directly connected to a private network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00292', 'gate-engineering-bank', 'Computer Networks', 4, 39, 'What is the difference between unicast, multicast, and broadcast transmission?', '**Unicast** sends data from one sender to exactly **one specific receiver**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00293', 'gate-engineering-bank', 'Computer Networks', 4, 40, 'What is the purpose of a Dynamic Host Configuration Protocol (DHCP) server?', 'A **DHCP server** automatically assigns **IP addresses and other network configuration parameters** (subnet mask, default gateway, DNS servers) to devices joining a network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00294', 'gate-engineering-bank', 'Computer Networks', 4, 41, 'What is the Bandwidth-Delay Product, and why is it important for determining optimal TCP window size?', 'The **Bandwidth-Delay Product (BDP)** is `bandwidth × round-trip time`, representing the maximum amount of **data that can be ''in flight''** on a link at any given moment.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00295', 'gate-engineering-bank', 'Computer Networks', 4, 42, 'What is a VLAN (Virtual LAN), and what benefit does it provide in a switched network?', 'A **VLAN** logically partitions a single physical switched network into multiple **isolated broadcast domains**, as if they were separate physical LANs, even though devices may be connected to the same physical switch.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00296', 'gate-engineering-bank', 'Computer Networks', 4, 43, 'What is the function of the Spanning Tree Protocol (STP) in Ethernet switched networks?', '**STP** prevents **bridge loops** in a network with redundant physical links between switches by logically disabling (blocking) certain redundant paths, ensuring a **single active loop-free path** exists between any two nodes.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00297', 'gate-engineering-bank', 'Computer Networks', 4, 44, 'What is the difference between a Man-In-The-Middle (MITM) attack and a Denial-of-Service (DoS) attack?', 'A **MITM attack** involves an attacker secretly **intercepting and potentially altering** communication between two parties who believe they are communicating directly with each other.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00298', 'gate-engineering-bank', 'Computer Networks', 4, 45, 'What is piggybacking in the context of data link layer acknowledgments?', '**Piggybacking** combines a data frame with the acknowledgment for previously received data in the **same frame**, rather than sending the ACK as a separate frame.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00299', 'gate-engineering-bank', 'Computer Networks', 4, 46, 'What is the Hidden Terminal Problem in wireless networks?', 'The **Hidden Terminal Problem** occurs when two stations, both within range of a common access point/receiver, are **not within range of each other**, so neither can detect the other''s transmission via carrier sensing.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00300', 'gate-engineering-bank', 'Computer Networks', 4, 47, 'What is the purpose of the Spanning Tree built by multicast routing protocols, and how does it differ from a unicast shortest-path tree?', 'Multicast routing builds a **spanning tree** (or a set of per-source trees) rooted at the source, connecting all group members with minimal redundant transmission.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00301', 'gate-engineering-bank', 'Computer Networks', 4, 48, 'What is the Maximum Transmission Unit (MTU), and what happens when a packet exceeds it?', 'The **MTU** is the largest size of a single data unit (frame/packet) that a particular network link can transmit without fragmentation (commonly 1500 bytes for standard Ethernet).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00302', 'gate-engineering-bank', 'Computer Networks', 4, 49, 'What is the role of the Border Gateway Protocol (BGP) in internet routing?', '**BGP** is the **path-vector routing protocol** used to exchange routing information **between autonomous systems (AS)** on the internet, making it the protocol that holds the global internet''s inter-domain routing together.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00303', 'gate-engineering-bank', 'Computer Networks', 4, 50, 'What is the difference between an Interior Gateway Protocol (IGP) and an Exterior Gateway Protocol (EGP), with one example of each?', 'An **IGP** (e.g., **OSPF** or **RIP**) handles routing **within a single autonomous system**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00304', 'gate-engineering-bank', 'Computer Networks', 4, 51, 'What is the purpose of the three-way handshake''s connection-termination counterpart, the four-way (FIN) termination process in TCP?', 'TCP connection termination typically uses a **four-step exchange**: the initiator sends **FIN**, the peer responds with **ACK**, the peer later sends its own **FIN** (once it has no more data to send), and the initiator responds with a final **ACK**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00305', 'gate-engineering-bank', 'Computer Networks', 4, 52, 'What is a socket in networking, and what two pieces of information uniquely identify it?', 'A **socket** is an endpoint for sending or receiving data across a network, used by applications via the sockets API.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00306', 'gate-engineering-bank', 'Computer Networks', 4, 53, 'What is the function of a proxy server in a network?', 'A **proxy server** acts as an intermediary between a client and the destination server, forwarding requests on the client''s behalf.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00307', 'gate-engineering-bank', 'Computer Networks', 4, 54, 'What is the significance of the well-known port range (0–1023) versus registered and dynamic/private port ranges?', '**Well-known ports (0–1023)** are reserved for standard, widely used services (e.g., HTTP on 80, FTP on 21), requiring administrative privileges to bind in most operating systems.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00308', 'gate-engineering-bank', 'Computer Networks', 4, 55, 'What is the difference between store-and-forward switching and cut-through switching?', '**Store-and-forward switching** receives an entire frame, checks it for errors (via CRC), and only then forwards it — introducing higher latency but better reliability.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00309', 'gate-engineering-bank', 'Computer Networks', 4, 56, 'What is the purpose of the window scaling TCP option?', 'The **window scaling option** extends TCP''s original 16-bit window size field (limited to 65,535 bytes) by applying a scale factor, allowing much **larger windows** to be advertised.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00310', 'gate-engineering-bank', 'Computer Networks', 4, 57, 'What is slow start threshold (ssthresh) in TCP congestion control, and how does it influence the transition between slow start and congestion avoidance?', '`ssthresh` marks the congestion window size below which TCP grows **exponentially (slow start)** and above which it grows **linearly, one MSS per RTT (congestion avoidance / AIMD)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00311', 'gate-engineering-bank', 'Computer Networks', 4, 58, 'What is Address Resolution Protocol (ARP) spoofing/poisoning, and what security risk does it pose?', '**ARP spoofing** involves an attacker sending forged ARP messages to associate their own MAC address with another device''s (often the gateway''s) IP address on the local network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00312', 'gate-engineering-bank', 'Computer Networks', 4, 59, 'What is the difference between a public IP address and a private IP address, giving one example private address range?', 'A **public IP address** is globally unique and routable directly on the internet.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00313', 'gate-engineering-bank', 'Computer Networks', 4, 60, 'What is the purpose of an Autonomous System Number (ASN) in internet routing?', 'An **ASN** uniquely identifies a collection of IP networks under the control of a **single administrative entity** (e.g., an ISP or large organization) that presents a common routing policy to the internet.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00314', 'gate-engineering-bank', 'Computer Networks', 4, 61, 'What is the function of the Preamble field in an Ethernet frame?', 'The **Preamble** (7 bytes) followed by the **Start Frame Delimiter (1 byte)** at the start of an Ethernet frame allows the receiver''s hardware to **synchronize its clock** with the incoming signal before the actual frame data begins.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00315', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 0, 'State Ohm''s Law and its formula.', '**Ohm''s Law** states that the current through a conductor between two points is **directly proportional to the voltage** across those points, for a constant temperature and resistance.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00316', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 1, 'State Kirchhoff''s Current Law (KCL) and Kirchhoff''s Voltage Law (KVL).', '**KCL**: the algebraic sum of currents entering a node equals the sum of currents leaving it (`Σ I_in = Σ I_out`) — a consequence of **charge conservation**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00317', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 2, 'What is Thevenin''s theorem, and what two quantities does it reduce a linear circuit to?', '**Thevenin''s theorem** states that any linear, bilateral electrical network, as seen from two output terminals, can be replaced by an **equivalent voltage source (Vth)** in series with an **equivalent resistance (Rth)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00318', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 3, 'What is Norton''s theorem, and how does it relate to Thevenin''s theorem?', '**Norton''s theorem** states that any linear circuit can be replaced by an **equivalent current source (IN)** in parallel with an **equivalent resistance (RN)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00319', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 4, 'State the Maximum Power Transfer Theorem for a DC circuit with a source resistance Rs.', 'The **Maximum Power Transfer Theorem** states that maximum power is delivered to a load when the **load resistance equals the Thevenin (source) resistance**: `RL = Rth`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00320', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 5, 'What is the Superposition Theorem, and what key assumption must the circuit satisfy for it to apply?', 'The **Superposition Theorem** states that in a **linear** circuit with multiple independent sources, the response (voltage or current) at any element equals the **algebraic sum** of the responses caused by each source acting alone (with all other independent sources deactivated).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00321', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 6, 'What is the RMS (root mean square) value of a sinusoidal AC voltage with peak value Vm?', 'The RMS value is `Vrms = Vm / √2 ≈ 0.707 Vm`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00322', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 7, 'What is the impedance of a pure inductor and a pure capacitor in an AC circuit at angular frequency ω?', 'The impedance of a pure **inductor** is `ZL = jωL`, which increases with frequency.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00323', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 8, 'What is the condition for resonance in a series RLC circuit, and what is the resonant frequency formula?', '**Resonance** in a series RLC circuit occurs when the **inductive and capacitive reactances are equal** (`XL = XC`), making the circuit''s impedance purely resistive and minimal.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00324', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 9, 'What is the power factor in an AC circuit, and what does a power factor of zero indicate?', 'The **power factor** is `cos(φ)`, where `φ` is the phase angle between voltage and current; it equals the ratio of **real (active) power** to **apparent power**: `PF = P/S`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00325', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 10, 'What is the difference between active power, reactive power, and apparent power in an AC circuit?', '**Active (real) power** `P = VI cos(φ)` (measured in watts) represents the power actually consumed/dissipated as useful work.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00326', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 11, 'What is the function of a PN junction diode, and what is the approximate cut-in (knee) voltage for a silicon diode?', 'A **PN junction diode** allows current to flow predominantly in **one direction** (forward bias) while blocking it in the reverse direction, due to the depletion region formed at the junction.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00327', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 12, 'What is Zener breakdown, and what is a Zener diode primarily used for?', '**Zener breakdown** occurs in a heavily doped PN junction when a sufficiently high **reverse voltage** causes a strong electric field that pulls electrons out of covalent bonds (a quantum tunneling-dominated effect at lower breakdown voltages).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00328', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 13, 'What are the three terminals of a Bipolar Junction Transistor (BJT), and what distinguishes an NPN from a PNP transistor?', 'The three terminals of a BJT are the **Emitter, Base, and Collector**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00329', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 14, 'What are the three regions of operation of a BJT, and which region is used for amplification?', 'The three regions are **Cut-off** (both junctions reverse biased — transistor acts as an open switch), **Saturation** (both junctions forward biased — transistor acts as a closed switch), and **Active region** (emitter-base forward biased, collector-base reverse biased).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00330', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 15, 'What is the difference between an enhancement-mode and a depletion-mode MOSFET?', 'An **enhancement-mode MOSFET** is normally OFF with zero gate-source voltage; applying a sufficient gate voltage **creates (enhances)** a conducting channel, turning it ON.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00331', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 16, 'What is the threshold voltage (Vt) of a MOSFET, and what determines whether it is operating in the triode (linear) or saturation region?', 'The **threshold voltage (Vt)** is the minimum gate-source voltage required to form a conducting channel (turn the MOSFET ON).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00332', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 17, 'What is an operational amplifier (op-amp), and what are its two key ''ideal'' assumptions used in circuit analysis?', 'An **op-amp** is a high-gain differential voltage amplifier IC with two inputs (inverting and non-inverting) and one output.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00333', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 18, 'What is the output voltage formula for an inverting op-amp amplifier with input resistor Rin and feedback resistor Rf?', 'The output voltage is `Vout = −(Rf/Rin) × Vin`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00334', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 19, 'State De Morgan''s theorems in Boolean algebra.', 'De Morgan''s first theorem: `(A + B)'' = A'' · B''` (the complement of a sum equals the product of the complements).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00335', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 20, 'What is a universal gate in digital logic, and name the two basic universal gates.', 'A **universal gate** is a logic gate that can be used, by itself, to implement **any** Boolean function (i.e., AND, OR, and NOT can all be constructed from it alone).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00336', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 21, 'What is a Karnaugh Map (K-map) used for in digital logic design?', 'A **K-map** is a graphical tool used to **simplify Boolean expressions** by visually grouping adjacent cells (minterms) that differ in only one variable, following **Gray code** adjacency.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00337', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 22, 'What is the difference between a combinational circuit and a sequential circuit?', 'A **combinational circuit''s** output depends **only on the current inputs**, with no memory of past inputs (e.g., adders, multiplexers, decoders).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00338', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 23, 'What is the fundamental difference between an SR latch and a D flip-flop?', 'An **SR latch** is a basic level-triggered (asynchronous) memory element with Set and Reset inputs, but it has an **undefined/forbidden state** when both S and R are asserted simultaneously.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00339', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 24, 'What is the characteristic equation of a JK flip-flop, and what happens when both J and K inputs are 1?', 'The characteristic equation is `Q(next) = J·Q'' + K''·Q`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00340', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 25, 'What is the difference between a synchronous counter and an asynchronous (ripple) counter?', 'In a **synchronous counter**, all flip-flops are triggered **simultaneously by the same clock signal**, so all outputs change at essentially the same time, avoiding propagation delay accumulation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00341', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 26, 'What is the function of a multiplexer (MUX), and how many select lines are needed for a 2^n-to-1 MUX?', 'A **multiplexer** selects **one of several input signals** and forwards it to a single output, based on the values of its select lines.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00342', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 27, 'What is the difference between a decoder and an encoder in digital logic?', 'A **decoder** converts an `n`-bit binary input into one of up to `2^n` distinct output lines, **activating exactly one** output line corresponding to the input code.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00343', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 28, 'What is the significance of propagation delay in digital circuits, and how does it limit the maximum clock frequency of a synchronous system?', '**Propagation delay** is the time taken for a change at a gate''s input to produce a corresponding change at its output.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00344', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 29, 'What is the turns ratio formula for an ideal transformer, relating voltage, current, and the number of turns in primary and secondary windings?', 'For an ideal transformer, `V1/V2 = N1/N2 = I2/I1`, where `N1, N2` are the primary and secondary turns, and `V, I` are the corresponding voltages and currents.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00345', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 30, 'What are the two main types of losses in a practical transformer, and what causes each?', '**Copper losses (I²R losses)** occur due to the resistance of the primary and secondary windings and vary with the **square of the load current**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00346', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 31, 'What is the principle of operation of a DC motor, and what law governs the force produced on a current-carrying conductor in a magnetic field?', 'A **DC motor** operates on the principle that a **current-carrying conductor placed in a magnetic field experiences a force**, converting electrical energy into mechanical (rotational) energy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00347', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 32, 'What is back EMF in a DC motor, and what role does it play in regulating armature current?', '**Back EMF (Eb)** is the voltage induced in the armature conductors as they rotate through the magnetic field, opposing the applied supply voltage, in accordance with **Lenz''s law**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00348', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 33, 'What is slip in an induction motor, and why can a three-phase induction motor never run at exactly synchronous speed?', '**Slip** `s = (Ns − Nr)/Ns` is the fractional difference between the **synchronous speed (Ns)** of the rotating magnetic field and the **actual rotor speed (Nr)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00349', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 34, 'What is the synchronous speed formula for a three-phase induction motor with P poles operating at frequency f?', 'The synchronous speed is **`Ns = 120f / P`** (in RPM), where `f` is the supply frequency in Hz and `P` is the number of poles.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00350', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 35, 'What is the transfer function of a control system, and under what initial condition is it defined?', 'The **transfer function** `G(s) = Output(s) / Input(s)` is the ratio of the Laplace transform of the output to the Laplace transform of the input, for a linear, time-invariant (LTI) system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00351', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 36, 'What is the Routh-Hurwitz stability criterion used for, and what condition on the Routh array indicates a stable system?', 'The **Routh-Hurwitz criterion** determines the **stability of a linear system** directly from its characteristic equation''s coefficients, without explicitly solving for the roots.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00352', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 37, 'What is the difference between an open-loop and a closed-loop (feedback) control system?', 'An **open-loop system** generates its output based solely on the input, with **no feedback** to compare actual output against the desired output, making it simpler but sensitive to disturbances and parameter variations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00353', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 38, 'What is the significance of poles and zeros of a transfer function in determining system stability?', '**Poles** of a transfer function are the values of `s` that make the denominator zero (and the transfer function infinite); for a stable LTI system, **all poles must lie in the left half of the s-plane** (negative real parts).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00354', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 39, 'What is the formula for equivalent resistance when n resistors are connected in series versus in parallel?', 'For resistors in **series**: `Req = R1 + R2 + ... + Rn` (resistances simply add).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00355', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 40, 'What is the time constant of an RC charging circuit, and what does it represent physically?', 'The time constant is `τ = RC`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00356', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 41, 'What is the time constant of an RL circuit, and how does it compare in formula structure to an RC circuit''s time constant?', 'The time constant of an RL circuit is `τ = L/R`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00357', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 42, 'What is the significance of the ''Q factor'' (quality factor) of a resonant RLC circuit?', 'The **Q factor** measures the **sharpness (selectivity)** of a resonant circuit''s frequency response — a higher Q indicates a narrower bandwidth and a more sharply peaked resonance.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00358', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 43, 'What is a half-wave rectifier, and what is its theoretical maximum efficiency?', 'A **half-wave rectifier** uses a single diode to convert only **one half-cycle** of an AC input into a pulsating DC output, blocking the other half-cycle entirely.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00359', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 44, 'What is the ripple factor of a rectifier circuit, and how does a full-wave rectifier compare to a half-wave rectifier in this regard?', 'The **ripple factor** quantifies the AC component remaining in a rectifier''s DC output, defined as the ratio of the RMS value of the AC ripple component to the DC component.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00360', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 45, 'What is the function of a filter capacitor placed after a rectifier circuit?', 'A **filter capacitor** smooths the pulsating DC output of a rectifier by **charging during voltage peaks and discharging during the gaps** between pulses, significantly reducing the ripple and producing a more constant DC voltage.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00361', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 46, 'What are the two Maxwell''s equations most relevant to understanding electromagnetic induction (Faraday''s Law) in integral form conceptually?', '**Faraday''s Law of electromagnetic induction** states that the **induced EMF** in a closed loop equals the **negative rate of change of magnetic flux** linking the loop: `EMF = −dΦ/dt`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00362', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 47, 'What does it mean for a two-port network to be reciprocal, and give an example of a reciprocal passive element.', 'A **reciprocal network** is one in which the **transfer impedance (or admittance) is the same regardless of which port is used as input and which as output** — i.e., interchanging the excitation and response ports doesn''t change the ratio measured.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00363', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 48, 'What is the significance of the h-parameters (hybrid parameters) commonly used to model a BJT in small-signal analysis?', '**h-parameters** characterize a two-port network using a mix of **open-circuit and short-circuit** conditions, convenient because they match directly measurable quantities for a transistor (input impedance `hie`, reverse voltage gain `hre`, forward current gain `hfe`, and output admittance `hoe`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00364', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 49, 'What is the difference between a voltage regulator IC in series configuration versus shunt configuration?', 'A **series regulator** controls output voltage by varying the **resistance of a series pass element** (e.g., a transistor) between input and output, dissipating excess voltage as heat — generally more efficient.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00365', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 50, 'What is the significance of the Barkhausen criterion for sustained oscillations in an oscillator circuit?', 'The **Barkhausen criterion** states that for sustained oscillations, the **loop gain must equal exactly unity (magnitude = 1)**, and the **total phase shift around the feedback loop must be exactly 0° (or a multiple of 360°)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00366', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 51, 'What is the function of a Schmitt trigger circuit, and what key property distinguishes it from a simple comparator?', 'A **Schmitt trigger** converts a noisy or slowly varying analog input into a clean digital (square-wave) output, switching states at two **different threshold voltages** depending on the direction of input change.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00367', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 52, 'What is the significance of the gain-bandwidth product (GBW) of an operational amplifier?', 'The **gain-bandwidth product** is approximately **constant** for a given op-amp (for a single-pole roll-off), meaning that as the closed-loop gain is increased, the usable **bandwidth decreases proportionally**, and vice versa.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00368', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 53, 'What is the function of a voltage follower (unity-gain buffer) op-amp configuration?', 'A **voltage follower** connects the op-amp output directly to its inverting input (100% negative feedback), producing an output that exactly follows the non-inverting input voltage (`gain = 1`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00369', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 54, 'What is skin effect in AC power transmission, and how does it affect conductor resistance at higher frequencies?', '**Skin effect** is the tendency of alternating current to concentrate near the **surface (skin)** of a conductor rather than flowing uniformly through its entire cross-section, becoming more pronounced at higher frequencies.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00370', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 55, 'What is the purpose of a CT (current transformer) and a PT (potential transformer) used in power system metering and protection?', 'A **current transformer (CT)** steps down a large primary current to a smaller, standardized secondary current (e.g., 5A or 1A) proportional to the original, safely enabling measurement with standard instruments.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00371', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 56, 'What is the significance of per-unit system representation in power system analysis?', 'The **per-unit system** expresses system quantities (voltage, current, power, impedance) as a **fraction (ratio) of a chosen base value**, rather than in absolute units.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00372', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 57, 'What is corona discharge in high-voltage transmission lines, and what factors increase its likelihood?', '**Corona discharge** is the ionization of air surrounding a high-voltage conductor when the **electric field at the conductor surface exceeds the breakdown strength of air**, producing a visible glow, audible hissing, and power loss.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00373', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 58, 'What is the difference between active (real) energy and reactive energy as measured by utility meters, and in what units is each measured?', '**Active energy** (measured in **kWh**) represents the actual useful energy consumed by a load to perform work (e.g., heating, mechanical motion, light).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00374', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 59, 'What is the function of a relay in a protection scheme for an electrical power system?', 'A **protective relay** continuously monitors system parameters (current, voltage, frequency) and automatically triggers a **circuit breaker to isolate a faulted section** of the power system when it detects abnormal conditions (e.g., overcurrent, short circuit, or overvoltage).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00375', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 60, 'What is the difference between an ammeter and a voltmeter in terms of how each should be ideally connected and its internal resistance?', 'An **ammeter** is connected in **series** with the circuit element whose current is being measured, and ideally has **near-zero internal resistance** to avoid altering the circuit''s current.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00376', 'gate-engineering-bank', 'Electrical & Electronics Basics', 5, 61, 'What is a Wheatstone bridge used for, and what is its balance condition?', 'A **Wheatstone bridge** is used to precisely measure an **unknown resistance** by comparing it against known resistances in a bridge configuration.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00377', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 0, 'State the Zeroth Law of Thermodynamics and its practical significance.', 'The **Zeroth Law** states that if two systems are each in thermal equilibrium with a third system, they are also in **thermal equilibrium with each other**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00378', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 1, 'State the First Law of Thermodynamics for a closed system.', 'The **First Law** (conservation of energy) states that the change in internal energy of a closed system equals the **heat added to the system minus the work done by the system**: `ΔU = Q − W`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00379', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 2, 'State the Second Law of Thermodynamics using the Kelvin-Planck statement.', 'The **Kelvin-Planck statement** says it is **impossible to construct a device that operates in a cycle and produces no effect other than extracting heat from a single reservoir and converting it entirely into work**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00380', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 3, 'What is the Carnot cycle, and why is its efficiency considered the theoretical maximum for any heat engine operating between two temperatures?', 'The **Carnot cycle** consists of two reversible isothermal processes and two reversible adiabatic processes.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00381', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 4, 'What is entropy, and what does the increase of entropy in an isolated system signify?', '**Entropy** is a thermodynamic property that measures the **degree of disorder or the unavailability of energy to do useful work** in a system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00382', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 5, 'What is the difference between an Otto cycle and a Diesel cycle in terms of the heat addition process?', 'In the **Otto cycle** (ideal cycle for spark-ignition/petrol engines), heat is added at **constant volume**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00383', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 6, 'What is the formula for the air-standard efficiency of an Otto cycle in terms of compression ratio r and specific heat ratio γ?', 'The air-standard efficiency is `η = 1 − 1/r^(γ−1)`, where `r` is the **compression ratio** and `γ = Cp/Cv` is the specific heat ratio.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00384', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 7, 'What is the Rankine cycle, and in what type of power plant is it commonly used?', 'The **Rankine cycle** is the ideal thermodynamic cycle for **steam power plants**, consisting of isentropic compression (pump), constant-pressure heat addition (boiler), isentropic expansion (turbine), and constant-pressure heat rejection (condenser).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00385', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 8, 'What is the difference between enthalpy and internal energy of a system?', '**Internal energy (U)** is the total energy stored within a system due to molecular motion and interactions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00386', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 9, 'What is the continuity equation in fluid mechanics, and what principle does it represent?', 'The **continuity equation**, `A1V1 = A2V2` (for incompressible flow), represents the principle of **conservation of mass** — the mass flow rate must remain constant through any cross-section of a pipe or duct with no leaks or sources.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00387', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 10, 'State Bernoulli''s equation and the key assumptions required for its validity.', '**Bernoulli''s equation**: `P/ρg + V²/2g + z = constant` along a streamline, representing the conservation of total mechanical energy (pressure, kinetic, and potential head) per unit weight of fluid.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00388', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 11, 'What is the Reynolds number, and what does it represent physically?', 'The **Reynolds number** `Re = ρVD/μ` (density × velocity × characteristic length / dynamic viscosity) is a dimensionless quantity representing the **ratio of inertial forces to viscous forces** in a fluid flow.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00389', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 12, 'What is the no-slip condition in fluid mechanics?', 'The **no-slip condition** states that a **real (viscous) fluid in contact with a solid boundary has zero relative velocity** with respect to that boundary — the fluid ''sticks'' to the surface.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00390', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 13, 'What is the relationship between shear stress and the velocity gradient for a Newtonian fluid?', 'For a **Newtonian fluid**, shear stress is **directly proportional** to the rate of shear strain (velocity gradient): `τ = μ (du/dy)`, where `μ` is the **dynamic viscosity**, a constant property of the fluid (at a given temperature) independent of the shear rate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00391', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 14, 'What is the difference between stress and strain, and what does Young''s Modulus represent?', '**Stress** is the internal **force per unit area** developed within a material in response to an applied external load (`σ = F/A`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00392', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 15, 'What is the relationship between the three elastic constants: Young''s Modulus (E), Shear Modulus (G), and Poisson''s ratio (ν)?', 'The relationship is **`E = 2G(1 + ν)`**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00393', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 16, 'What is Poisson''s ratio, and what is its typical range of values for common engineering materials?', '**Poisson''s ratio** `ν` is the ratio of **lateral (transverse) strain to longitudinal (axial) strain** when a material is stretched or compressed: `ν = −ε_lateral / ε_axial`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00394', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 17, 'What is the difference between a brittle material and a ductile material in terms of their stress-strain behavior?', 'A **ductile material** (e.g., mild steel, aluminum) undergoes **significant plastic deformation** before fracture, exhibiting a distinct yield point and necking region on its stress-strain curve.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00395', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 18, 'What is the formula for bending stress in a beam, and what does each term (M, y, I) represent?', 'The bending stress formula is `σ = My/I`, where `M` is the **bending moment** at the section, `y` is the **distance from the neutral axis** to the point where stress is evaluated, and `I` is the **second moment of area (moment of inertia)** of the cross-section about the neutral axis.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00396', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 19, 'What is the formula for shear stress due to torsion in a circular shaft, and what does J represent?', 'The torsion formula is `τ/r = T/J = Gθ/L`, where `T` is the applied torque, `r` is the radial distance from the shaft''s axis, `J` is the **polar moment of inertia** of the cross-section, `G` is the shear modulus, `θ` is the angle of twist, and `L` is the shaft length.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00397', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 20, 'What is the difference between a simply supported beam and a cantilever beam in terms of support conditions?', 'A **simply supported beam** rests on supports at **both ends** (typically one pin/hinge support and one roller support), allowing rotation but no vertical displacement at the supports.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00398', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 21, 'What is the maximum deflection formula for a simply supported beam of length L with a central point load W and flexural rigidity EI?', 'The maximum deflection (at the center) is `δmax = WL^3 / (48EI)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00399', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 22, 'What is Euler''s formula for the critical buckling load of a long column, and what key parameter captures the effect of end conditions?', '**Euler''s buckling formula**: `Pcr = (π² EI) / (Le)^2`, where `Le` is the **effective length** of the column, which accounts for different end conditions (e.g., `Le = L` for pinned-pinned, `Le = 2L` for fixed-free, `Le = 0.5L` for fixed-fixed).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00400', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 23, 'What is the difference between a stress concentration factor and a factor of safety in machine design?', 'A **stress concentration factor (Kt)** quantifies how much **local stress is amplified** near a geometric discontinuity (hole, notch, fillet) compared to the nominal (average) stress.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00401', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 24, 'What is fatigue failure in machine components, and what is the significance of the endurance limit?', '**Fatigue failure** is the progressive, localized structural damage that occurs when a material is subjected to **cyclic (repeated) loading**, often at stress levels well below the material''s static yield strength.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00402', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 25, 'What is the function of a flywheel in a machine, and what property allows it to perform this function?', 'A **flywheel** stores **kinetic energy** during periods of excess energy supply (e.g., the power stroke of an engine) and releases it during periods of energy deficit, **smoothing out fluctuations in angular velocity** over a machine cycle.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00403', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 26, 'What is the difference between a flywheel and a governor in controlling machine speed?', 'A **flywheel** controls **cyclic speed fluctuations within a single revolution/cycle** caused by non-uniform torque (e.g., in a single-cylinder engine), acting as a short-term energy buffer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00404', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 27, 'What is the velocity ratio of a simple gear train, and how is it calculated for two meshing spur gears?', 'The **velocity ratio** of two meshing spur gears is the **inverse ratio of their number of teeth**: `N1/N2 = T2/T1` (where `N` is speed and `T` is the number of teeth).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00405', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 28, 'What is the law of gearing, and why must gear tooth profiles satisfy it for smooth, constant-velocity-ratio power transmission?', 'The **law of gearing** requires that the **common normal to the tooth profiles at the point of contact must always pass through a fixed point** on the line joining the centers of the two gears (the **pitch point**).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00406', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 29, 'What is the purpose of a cam-follower mechanism, and what is one common type of motion a follower can be designed to execute?', 'A **cam-follower mechanism** converts rotary motion of the cam into a desired (often reciprocating) motion of the follower, following a profile designed for a specific motion requirement.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00407', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 30, 'What is static and dynamic balancing of rotating machinery, and why is balancing important?', '**Static balancing** ensures the **center of mass of a rotating body lies on its axis of rotation**, so it remains at rest in any angular position without external torque.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00408', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 31, 'What is the coefficient of friction, and what is the key difference between static and kinetic (dynamic) friction?', 'The **coefficient of friction (μ)** is the ratio of the **friction force to the normal force** between two surfaces in contact: `f = μN`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00409', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 32, 'What is the principle of virtual work, and how is it used to analyze equilibrium of mechanical systems?', 'The **principle of virtual work** states that a system is in **equilibrium if and only if the total virtual work done by all applied forces during any small virtual (hypothetical) displacement consistent with the system''s constraints is zero**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00410', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 33, 'What is D''Alembert''s principle, and how does it convert a dynamics problem into an equivalent statics problem?', '**D''Alembert''s principle** states that by introducing a fictitious **''inertia force''** equal in magnitude but opposite in direction to the product of mass and acceleration (`−ma`), a dynamic system can be analyzed using the **same equilibrium equations (ΣF = 0, ΣM = 0) used in statics**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00411', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 34, 'What is the difference between conduction, convection, and radiation as modes of heat transfer?', '**Conduction** transfers heat through direct **molecular/atomic interaction within a stationary medium** (solid or fluid), governed by **Fourier''s Law**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00412', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 35, 'State Fourier''s Law of heat conduction and its formula for one-dimensional steady-state conduction through a plane wall.', '**Fourier''s Law**: the rate of heat conduction is proportional to the **negative temperature gradient** and the **area** perpendicular to the direction of heat flow: `Q = −kA(dT/dx)`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00413', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 36, 'What is the significance of the Biot number in heat transfer analysis?', 'The **Biot number** `Bi = hL_c/k` (surface convective coefficient × characteristic length / internal thermal conductivity) compares the **relative resistance to heat transfer within a solid body versus at its surface**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00414', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 37, 'What is black body radiation, and what law relates the total energy radiated per unit area to its absolute temperature?', 'A **black body** is an idealized surface that **absorbs all incident radiation** (and, being a perfect absorber, is also the most efficient possible emitter at any given temperature).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00415', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 38, 'What is the difference between the casting processes of sand casting and die casting?', '**Sand casting** uses a **disposable mold made of compacted sand**, suitable for low-volume production, large parts, and a wide variety of metals, but with relatively **rough surface finish and lower dimensional accuracy**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00416', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 39, 'What is the difference between arc welding and gas welding as fusion welding processes?', '**Arc welding** generates intense heat using an **electric arc** struck between an electrode and the workpiece, achieving very high, localized temperatures suitable for thick sections and structural steel.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00417', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 40, 'What is the difference between orthogonal cutting and oblique cutting in machining?', 'In **orthogonal cutting**, the cutting edge of the tool is **perpendicular to the direction of relative tool-workpiece motion**, resulting in a two-dimensional chip flow (idealized, simplified model).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00418', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 41, 'What are the three basic types of chips formed during metal cutting operations?', 'The three basic chip types are: **continuous chips** (formed with ductile materials at high cutting speeds and low friction, producing good surface finish), **discontinuous (segmented) chips** (formed with brittle materials or at low cutting speeds, producing small fragmented pieces), and **continuous chips with a built-up edge (BUE)** (formed due to work-material adhesion to the tool face, often degrading surface finish).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00419', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 42, 'What is tool wear in machining, and what are the two primary locations where it typically occurs on a cutting tool?', '**Tool wear** is the gradual degradation of a cutting tool''s edge and surface due to the mechanical, thermal, and chemical interactions during the cutting process.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00420', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 43, 'What is the difference between interchangeable and selective assembly in manufacturing, in the context of fits and tolerances?', '**Interchangeable assembly** allows any part from a batch (manufactured within specified tolerances) to be assembled with **any mating part** from another batch, without the need for selective matching or rework — essential for mass production.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00421', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 44, 'What is the difference between a clearance fit, an interference fit, and a transition fit in limits, fits, and tolerances?', 'A **clearance fit** always leaves a **positive gap** between mating parts (shaft is always smaller than the hole), allowing free relative movement.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00422', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 45, 'What is the function of a vernier caliper, and what is the typical least count achievable with a standard vernier scale?', 'A **vernier caliper** measures linear dimensions (external, internal, and depth) with higher precision than a plain ruler, using a **main scale and a sliding vernier scale** whose graduations are offset to allow fractional readings of the main scale''s smallest division.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00423', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 46, 'What is the working principle of a micrometer screw gauge, and what determines its typical least count?', 'A **micrometer screw gauge** measures small linear dimensions precisely using the relationship between the **rotation of a calibrated screw** and its linear axial advancement (pitch).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00424', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 47, 'What is the difference between accuracy and precision in a measurement system?', '**Accuracy** describes how **close a measured value is to the true (actual) value**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00425', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 48, 'What is the difference between work and heat as forms of energy transfer in thermodynamics?', '**Work** is energy transfer associated with a **force acting through a displacement**, occurring via an organized (macroscopically observable) mechanism (e.g., a piston moving, a shaft rotating).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00426', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 49, 'What is specific heat at constant volume (Cv) versus specific heat at constant pressure (Cp) for an ideal gas, and how are they related?', '`Cv` is the heat required to raise the temperature of a unit mass of gas by one degree at **constant volume**; `Cp` is the corresponding value at **constant pressure**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00427', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 50, 'What is a throttling process, and what happens to the enthalpy of a fluid during an ideal (adiabatic, no-work) throttling process?', 'A **throttling process** involves a fluid flowing through a **restriction (like a valve or porous plug)**, causing a sudden pressure drop, typically without any significant heat transfer or work output.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00428', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 51, 'What is the significance of the Joule-Thomson coefficient, and what does a positive value indicate?', 'The **Joule-Thomson coefficient** `μJT = (∂T/∂P)h` measures the **change in temperature of a real gas during a throttling (isenthalpic) process** per unit change in pressure.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00429', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 52, 'What is the degree of freedom of a mechanism, and what formula (Kutzbach/Gruebler criterion) is used to calculate it for a planar mechanism?', 'The **degree of freedom (DOF)** of a mechanism is the number of **independent input motions** required to fully define the position of every link in the mechanism.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00430', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 53, 'What is the difference between a mechanism and a structure in terms of degrees of freedom?', 'A **mechanism** has a **positive degree of freedom (DOF ≥ 1)**, meaning it can undergo relative motion between its links when driven by an input.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00431', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 54, 'What is the significance of the Grashof''s law for a four-bar linkage mechanism?', '**Grashof''s law** states that a four-bar linkage will have **at least one link capable of making a full revolution relative to the others** if and only if the sum of the **shortest and longest link lengths is less than or equal to** the sum of the two intermediate link lengths.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00432', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 55, 'What is the function of a boiler''s safety valve, and at what condition does it operate?', 'A **safety valve** automatically **releases excess steam/pressure** from a boiler when the internal pressure exceeds a pre-set safe limit, protecting the boiler from catastrophic over-pressure failure.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00433', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 56, 'What is the significance of the compression ratio in internal combustion engines, and what practical limit restricts how high it can be set in a spark-ignition (petrol) engine?', 'The **compression ratio** is the ratio of the cylinder volume at bottom dead center to the volume at top dead center, and higher compression ratios generally improve **thermal efficiency**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00434', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 57, 'What is the difference between impulse and reaction turbines in terms of how pressure energy is converted?', 'In an **impulse turbine** (e.g., Pelton wheel), the **entire pressure drop occurs in fixed nozzles** before the fluid strikes the moving blades, so pressure remains constant as the fluid passes over the rotor blades (only kinetic energy changes).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00435', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 58, 'What is cavitation in hydraulic machinery, and why is it damaging?', '**Cavitation** occurs when local fluid pressure drops **below the vapor pressure** of the liquid, causing vapor bubbles to form; these bubbles then **collapse violently** when they move to regions of higher pressure.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00436', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 59, 'What is the difference between a parallel-flow and a counter-flow heat exchanger arrangement?', 'In a **parallel-flow heat exchanger**, the hot and cold fluids flow in the **same direction**, so the temperature difference between them is largest at the inlet and decreases along the length.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00437', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 60, 'What is creep in engineering materials, and under what conditions does it become significant?', '**Creep** is the **slow, time-dependent plastic deformation** of a material under a constant (often sustained) stress, typically well below its yield strength.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00438', 'gate-engineering-bank', 'Mechanical Engineering Basics', 6, 61, 'What is the slenderness ratio of a column, and how does it influence the mode of failure?', 'The **slenderness ratio** is the ratio of a column''s **effective length to its minimum radius of gyration** (`Le/k`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00439', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 0, 'What is the degree of static indeterminacy of a structure, and what does a value of zero indicate?', 'The **degree of static indeterminacy** is the number of **additional (redundant) equations** needed, beyond the basic static equilibrium equations, to fully solve for all unknown forces/reactions in a structure.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00440', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 1, 'What is the formula for the static indeterminacy of a plane truss, in terms of members (m), reactions (r), and joints (j)?', 'The degree of static indeterminacy of a plane truss is `DS = m + r − 2j`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00441', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 2, 'What is a bending moment diagram (BMD), and what does the slope of the shear force diagram (SFD) represent?', 'A **bending moment diagram** shows the variation of bending moment along the length of a beam, essential for identifying the location and magnitude of maximum bending stress.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00442', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 3, 'At a point of zero shear force in a simply supported beam under transverse loading, what can be said about the bending moment?', 'At a point of **zero shear force**, the bending moment is at a **local maximum or minimum** (an extremum), since `dM/dx = V = 0` at that point.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00443', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 4, 'What is the difference between Ordinary Portland Cement (OPC) and Pozzolana Portland Cement (PPC)?', '**OPC** is produced by grinding clinker with gypsum, offering **higher early strength** and faster setting, commonly used in general construction.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00444', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 5, 'What is the typical water-cement ratio range used in concrete, and what is its effect on concrete strength according to Abrams'' law?', '**Abrams'' Law** states that, for a given set of materials, the **strength of fully compacted concrete is inversely related to the water-cement ratio** — a lower w/c ratio (typically in the range of **0.3 to 0.6** for structural concrete) produces higher compressive strength, provided adequate workability for proper compaction is maintained.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00445', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 6, 'What is the slump test used for in concrete technology, and what property does it measure?', 'The **slump test** measures the **workability (consistency) of fresh concrete** by filling a standard conical mould with concrete, removing the mould, and measuring the vertical settlement (slump) of the concrete.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00446', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 7, 'Why is concrete typically cured for a minimum of 28 days before full design strength is assumed?', '**Curing** maintains adequate moisture and temperature to allow the **hydration reaction of cement** to continue, which progressively increases concrete strength over time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00447', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 8, 'What is the significance of the modular ratio in reinforced concrete design using the Working Stress Method?', 'The **modular ratio** `m = Es/Ec` (ratio of the modulus of elasticity of steel to that of concrete) is used to **transform the steel reinforcement area into an equivalent area of concrete**, allowing the composite reinforced concrete section to be analyzed as a single homogeneous material in elastic (working stress) design calculations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00448', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 9, 'What is the difference between the Working Stress Method (WSM) and the Limit State Method (LSM) of reinforced concrete design?', 'The **Working Stress Method** designs members to keep stresses **within permissible elastic limits** under service (working) loads, using a single overall factor of safety.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00449', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 10, 'What is the purpose of providing a minimum clear cover to reinforcement in an RCC member?', '**Clear cover** protects the reinforcement from **corrosion** (by limiting the ingress of moisture and carbon dioxide/chlorides) and provides adequate **fire resistance**, while also ensuring sufficient **bond** between steel and concrete.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00450', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 11, 'What is the difference between a one-way slab and a two-way slab in RCC design?', 'A **one-way slab** has its longer span-to-shorter span ratio **greater than 2**, so it predominantly bends and transfers load in **one direction only**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00451', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 12, 'What is the function of shear reinforcement (stirrups) in an RCC beam?', '**Stirrups** resist the **diagonal tension** that develops in a beam due to the combined action of bending and shear stresses, preventing sudden, brittle **diagonal (shear) cracking and failure**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00452', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 13, 'What is the difference between an index property and an engineering property of soil?', '**Index properties** (e.g., water content, specific gravity, Atterberg limits, grain size distribution) are **relatively simple to measure** and used to **classify and identify** soil types.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00453', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 14, 'What are the Atterberg limits, and what do the Liquid Limit and Plastic Limit represent?', 'The **Atterberg limits** define the water content boundaries between different consistency states of fine-grained (cohesive) soil.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00454', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 15, 'What does Darcy''s Law describe in geotechnical/groundwater engineering, and what is its formula?', '**Darcy''s Law** describes the flow of water through a **saturated porous medium (soil)**: `v = ki`, where `v` is the discharge (Darcy) velocity, `k` is the **coefficient of permeability**, and `i` is the **hydraulic gradient**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00455', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 16, 'What is the coefficient of permeability of soil, and how does it typically compare between clay and sand?', 'The **coefficient of permeability (k)** quantifies how easily water flows through a soil''s pore spaces, measured typically in cm/s or m/day.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00456', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 17, 'What is consolidation of soil, and how does it differ from immediate (elastic) settlement?', '**Consolidation** is the **gradual, time-dependent reduction in soil volume** due to the expulsion of pore water from saturated, fine-grained (typically clayey) soil under sustained load, governed by Terzaghi''s theory of consolidation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00457', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 18, 'What is the Mohr-Coulomb failure criterion for soil shear strength, and what does it relate?', 'The **Mohr-Coulomb criterion** relates the **shear strength (τf)** of soil at failure to the **normal stress (σ)** acting on the failure plane: `τf = c + σ tan(φ)`, where `c` is the **cohesion** and `φ` is the **angle of internal friction**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00458', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 19, 'What is the significance of Terzaghi''s bearing capacity theory for shallow foundations?', '**Terzaghi''s bearing capacity theory** estimates the **ultimate bearing capacity** of soil beneath a shallow foundation by combining the contributions of soil **cohesion, surcharge (overburden), and self-weight of the soil within the failure wedge**, each weighted by its own **bearing capacity factor** (`Nc, Nq, Nγ`), which depend on the soil''s angle of internal friction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00459', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 20, 'What is the difference between a shallow foundation and a deep foundation, and when is a deep foundation typically chosen?', 'A **shallow foundation** (e.g., isolated/combined footings, raft foundation) transfers load to soil at a **relatively shallow depth**, typically where depth is comparable to or less than the foundation''s width.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00460', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 21, 'What is the purpose of a pile foundation, and what are the two primary mechanisms by which it transfers load to the surrounding soil?', 'A **pile foundation** transfers structural loads to deeper, more competent soil/rock strata when shallow foundations are inadequate.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00461', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 22, 'What is the Manning''s equation used for in open channel flow, and what does the roughness coefficient ''n'' represent?', '**Manning''s equation**, `V = (1/n) R^(2/3) S^(1/2)`, estimates the average **flow velocity** in open channel (uniform, free-surface) flow, where `R` is the hydraulic radius and `S` is the channel bed slope.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00462', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 23, 'What is the hydraulic radius of an open channel, and how is it calculated?', 'The **hydraulic radius** `R = A/P` is the ratio of the **cross-sectional flow area (A)** to the **wetted perimeter (P)** — the length of the channel boundary in contact with the flowing water.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00463', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 24, 'What is the difference between a sub-critical, critical, and super-critical flow regime in open channel hydraulics (based on the Froude number)?', '**Sub-critical flow** (`Fr < 1`) is relatively slow and deep, dominated by gravity, where disturbances can propagate upstream.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00464', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 25, 'What is the function of a weir in open channel hydraulics, and what does its discharge formula typically depend on?', 'A **weir** is an obstruction placed across a channel to **measure or control the flow rate** of water, causing water to pond and flow over (or through) a notch of known geometry.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00465', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 26, 'What is the purpose of benchmarking (reduced levels) in surveying and leveling?', 'A **Bench Mark (BM)** is a point of **known, fixed elevation (Reduced Level)** used as a reference for determining the elevations of other points during leveling operations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00466', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 27, 'What is the difference between a traverse survey and a triangulation survey?', 'A **traverse survey** determines positions of points by measuring a connected series of **lengths and angles (or bearings)** between successive points, forming an open or closed polygon.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00467', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 28, 'What is the function of a total station instrument in modern surveying?', 'A **total station** combines an **electronic theodolite (for measuring angles)** with an **Electronic Distance Measurement (EDM)** device (for measuring distances) into a single integrated instrument.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00468', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 29, 'What is the purpose of contour lines on a topographic map, and what does closely spaced contours indicate?', 'A **contour line** connects points of **equal elevation** on the ground, providing a visual representation of terrain shape and slope on a 2D map.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00469', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 30, 'What is Biochemical Oxygen Demand (BOD), and what does it measure in wastewater quality assessment?', '**BOD** measures the **amount of dissolved oxygen consumed by microorganisms** while biologically decomposing organic matter in a water/wastewater sample, typically measured over a **5-day period at 20°C (BOD5)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00470', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 31, 'What is the difference between BOD and COD (Chemical Oxygen Demand) as water quality parameters?', '**BOD** measures oxygen consumed specifically by **biological (microbial) degradation** of organic matter, and only accounts for **biodegradable** material.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00471', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 32, 'What is the purpose of coagulation and flocculation in water treatment?', '**Coagulation** involves adding a chemical coagulant (e.g., alum) to **destabilize fine suspended/colloidal particles**, neutralizing their natural electrostatic repulsion.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00472', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 33, 'What is the typical sequence of unit operations in a conventional water treatment plant?', 'A typical sequence is: **screening** (removing large debris), **coagulation and flocculation** (aggregating fine particles), **sedimentation** (settling out flocs), **filtration** (removing remaining fine particles, typically through sand filters), and **disinfection** (typically chlorination, to kill pathogenic microorganisms) before distribution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00473', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 34, 'What is the purpose of a septic tank in on-site sanitation, and what two processes occur within it?', 'A **septic tank** provides on-site primary treatment of domestic wastewater for individual or small-community systems without access to a centralized sewer network.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00474', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 35, 'What is the California Bearing Ratio (CBR) test used for in pavement design?', 'The **CBR test** measures the **relative strength of a subgrade/base material** by comparing the penetration resistance of the test soil to that of a standard crushed stone material under identical conditions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00475', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 36, 'What is the difference between a flexible pavement and a rigid pavement in highway engineering?', 'A **flexible pavement** (e.g., bituminous/asphalt roads) consists of multiple layers that distribute load gradually over a wider area through **grain-to-grain contact**, deflecting slightly under load, with load transfer decreasing with depth.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00476', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 37, 'What is superelevation (banking) in highway design, and why is it provided on horizontal curves?', '**Superelevation** is the **transverse slope (banking)** provided on a horizontal road curve, raising the outer edge relative to the inner edge.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00477', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 38, 'What is the purpose of providing a camber (crown) on a road''s cross-section?', '**Camber** is the slight convex curvature (cross-slope) provided on a road''s surface, highest at the center and sloping down towards the edges.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00478', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 39, 'What is the function of an irrigation canal''s ''duty'' and ''delta'' in agricultural water management?', '**Delta** is the **total depth of water required** by a crop during its entire growing period (base period) to mature successfully.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00479', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 40, 'What is the difference between a gravity dam and an earthen (embankment) dam in terms of how each resists water pressure?', 'A **gravity dam** (typically concrete/masonry) resists the horizontal water pressure primarily through its **own weight**, which generates sufficient frictional resistance and moment stability against the overturning/sliding forces of the reservoir water.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00480', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 41, 'What is the Modulus of Elasticity of standard structural steel typically used in design codes, in comparison to that of concrete?', 'The modulus of elasticity of structural **steel** is typically taken as about `Es ≈ 200 GPa (2 × 10^5 N/mm²)`, which is essentially constant regardless of grade.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00481', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 42, 'What is the significance of the neutral axis in a bending member, and where is it located for a homogeneous symmetric section?', 'The **neutral axis** is the axis within a bending cross-section where the **bending stress is zero** — fibers above experience one type of stress (tension or compression) and fibers below experience the opposite.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00482', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 43, 'What is the difference between a pin-jointed truss and a rigid-jointed frame in structural analysis?', 'In a **pin-jointed (truss) structure**, joints are assumed to be **frictionless hinges** that transmit only **axial force** (tension or compression), with members theoretically carrying no bending moment.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00483', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 44, 'What is the method of joints used for in truss analysis, and what key assumption does it rely on at each joint?', 'The **method of joints** analyzes a truss by considering the **equilibrium of forces at each individual joint** (since joints are pin-connected, only two independent equilibrium equations, `ΣFx=0` and `ΣFy=0`, apply at each joint in a planar truss).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00484', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 45, 'What is the significance of soil''s liquefaction potential, and under what condition is it most likely to occur?', '**Liquefaction** is the sudden, dramatic **loss of soil shear strength** when saturated, loose, cohesionless soil (typically fine sand) is subjected to rapid cyclic loading (most commonly earthquake shaking), causing pore water pressure to rise sharply and approach the total overburden stress.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00485', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 46, 'What is the purpose of providing an expansion joint in a long concrete structure like a bridge or pavement?', 'An **expansion joint** provides a deliberate gap/discontinuity in a long structure to accommodate **dimensional changes due to thermal expansion and contraction** (and sometimes shrinkage/creep), preventing the buildup of excessive internal stresses that could otherwise cause **cracking or buckling**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00486', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 47, 'What is the difference between dead load and live load in structural design?', '**Dead load** refers to the **permanent, constant weight** of the structure itself and any permanently fixed elements (self-weight, finishes, fixed partitions), which does not change over time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00487', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 48, 'What is the function of a retaining wall, and what are the two primary earth pressure conditions considered in its design?', 'A **retaining wall** resists the lateral pressure exerted by retained soil (or other material) to prevent it from collapsing or sliding, maintaining a difference in ground elevation on either side.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00488', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 49, 'What is Rankine''s theory of earth pressure, and what key assumption does it make about the wall-soil interface?', '**Rankine''s theory** calculates lateral earth pressure based on the state of **plastic equilibrium within the soil mass itself**, assuming the retaining wall surface is **perfectly smooth (frictionless)** and vertical, with a horizontal backfill surface.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00489', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 50, 'What is the significance of the factor of safety against sliding and overturning in retaining wall design?', 'The **factor of safety against sliding** ensures the wall''s resisting friction/shear force at its base **sufficiently exceeds** the horizontal driving force from active earth pressure, typically requiring a minimum value (commonly around 1.5).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00490', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 51, 'What is the significance of specific gravity and water absorption tests for coarse aggregates used in concrete?', '**Specific gravity** of aggregate indicates its **density and relative quality** (denser aggregates are generally stronger and more durable), and is used in concrete mix design calculations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00491', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 52, 'What is the difference between a Fink truss and a Howe/Pratt truss in roof/bridge truss configurations?', 'Different truss configurations (**Howe, Pratt, Fink, Warren**, etc.) arrange diagonal and vertical members differently to efficiently carry loads with members predominantly in **tension or compression** depending on the loading direction and span.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00492', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 53, 'What does the term ''factor of safety'' mean in the context of soil bearing capacity for foundation design?', 'The **factor of safety** for bearing capacity is the ratio of the soil''s **ultimate bearing capacity to the safe (allowable) bearing pressure** applied by the foundation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00493', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 54, 'What is the purpose of a sewerage system''s ''self-cleansing velocity'', and why is it important?', '**Self-cleansing velocity** is the minimum flow velocity in a sewer required to **prevent the settling and accumulation of suspended solids** within the pipe, which could otherwise cause blockages and odor problems.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00494', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 55, 'What is the principle behind the use of geotextiles in civil engineering applications like road construction and drainage?', '**Geotextiles** are permeable synthetic fabrics used to perform functions such as **separation** (preventing mixing of different soil/aggregate layers), **filtration** (allowing water to pass while retaining soil particles), **drainage** (channeling water within their plane), and **reinforcement** (improving soil''s tensile capacity), improving the performance and longevity of roads, embankments, and drainage systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00495', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 56, 'What is the effective stress principle in soil mechanics, as proposed by Terzaghi?', '**Terzaghi''s effective stress principle** states that the behavior of saturated soil (deformation and shear strength) is governed by **effective stress**, defined as `σ'' = σ − u`, where `σ` is the **total stress** and `u` is the **pore water pressure**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00496', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 57, 'What is the difference between permanent (plastic) and recoverable (elastic) deformation in pavement materials under traffic loading?', '**Elastic (recoverable) deformation** is the portion of deformation under load that **fully recovers** once the load is removed, representing temporary flexing of the pavement structure.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00497', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 58, 'What is the Standard Penetration Test (SPT) used for in geotechnical site investigation, and what does the N-value represent?', 'The **SPT** is an in-situ field test that measures a soil''s **relative density and strength** by driving a standard split-spoon sampler into the ground using a standard hammer drop and counting blows.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00498', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 59, 'What is the purpose of the Standard Proctor Compaction Test, and what two key values does it determine?', 'The **Standard Proctor Test** determines the relationship between a soil''s **moisture content and its dry density** when compacted with a standard compactive effort.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00499', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 60, 'What is the difference between an under-reinforced and an over-reinforced RCC beam section, and which is preferred in design?', 'In an **under-reinforced section**, the steel reinforcement **yields before the concrete crushes**, giving ample warning (large deflection and visible cracking) before eventual failure — a **ductile** failure mode.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('gate-q00500', 'gate-engineering-bank', 'Civil Engineering Basics', 7, 61, 'What is the Critical Path Method (CPM) in construction project management, and what does the ''critical path'' represent?', '**CPM** is a project scheduling technique that models a project as a **network of activities** with defined durations and dependencies, calculating the **earliest and latest start/finish times** for each activity.
